import { Link } from "react-router-dom";

// Long-form Farm Trails guide bodies, keyed by slug. Imported only by the app
// (src/App.jsx) — never by the Node sitemap script. Metadata (title, area,
// blurb, published flag) lives in farm-trails-index.js. To publish a guide,
// flip `published: true` there once its body exists here.
//
// Generated deterministically from the source markdown guides; every business
// links to its /listing/:slug page.

// Inline link to a directory listing — keeps the prose readable.
function L({ to, children }) {
  return <Link to={`/listing/${to}`}>{children}</Link>;
}

export const FARM_TRAIL_BODIES = {
  "a-saturday-around-oak-hill": () => (
    <>
      <p className="trail-lede">Tucked into the northern Greene County foothills along the Catskill Creek, Oak Hill is one of the best-preserved 19th-century hamlets in the region — a National Register historic district of old storefronts and farmhouses where the Catskills begin to rise. The surrounding Durham Valley is quieter and lower than the mountaintop resort towns, and it's some of the most authentic working-farm country anywhere in the Almanac: eighth-generation farms, honor-system stands down every back road, sugarhouses that have been boiling sap for over a century, and a couple of good breweries to finish on. This guide stays close to home — Oak Hill and the farms within easy reach. Here's a Saturday in the valley.</p>
      <h2 className="trail-h2">Morning — Oak Hill &amp; Durham</h2>
      <p>Start in Oak Hill itself. The hamlet rewards a slow walk — the historic streetscape along the creek, the antique shops, the sense of a place that time mostly left alone. Just outside the village, <strong><L to="resilient-roots-farm">Resilient Roots Farm</L></strong> raises pasture-grazed chickens on organic, soy-free feed and sells from a farm stand, and <strong><L to="woodworking-of-oak-hill">Woodworking of Oak Hill</L></strong> turns out custom cabinetry and wood goods.</p>
      <p>A few minutes on, <strong><L to="hull-o-farms">Hull-O Farms</L></strong> in Durham is the anchor of the whole valley — an eighth-generation working farm designated a New York State Bicentennial Farm for more than 200 years of continuous family stewardship. It runs as a livestock farm, a beloved family farm-stay where guests milk cows and gather eggs, and a licensed shooting preserve, all on 300-plus acres of the northern Catskills. Nearby, <strong><L to="lazy-day-farm">Lazy Day Farm</L></strong> grows rare and heirloom produce and flowers, with jams, syrups, and unusually colored eggs.</p>
      <h2 className="trail-h2">Late morning — East Durham</h2>
      <p>East Durham is the "Irish Catskills," a resort hamlet with deep Irish heritage and a cultural center to match — but it's also farm-rich. <strong><L to="east-durham-farms">East Durham Farms</L></strong> keeps a two-story barn store stocked with its own pasture-raised meats, local cheeses, maple, and baked goods, with U-pick apples, peaches, and flowers in season. For fiber, <strong><L to="greene-county-wool">Greene County Wool</L></strong> raises a flock of rare Romeldale CVM sheep and sells raw fleece, yarn, and roving, and <strong><L to="hedges-homestead">Hedges Homestead</L></strong> makes pure maple syrup, cream, and candy across six and seven generations of family tradition.</p>
      <h2 className="trail-h2">Midday — Cornwallville, Freehold &amp; Greenville</h2>
      <p>The farms thicken as you loop east and north. In Cornwallville, <strong><L to="greene-farms">Greene Farms</L></strong> revived a long-fallow organic vegetable property on historic Stone Bridge Road. Around Freehold, <strong><L to="rolling-hill-farm">Rolling Hill Farm</L></strong> grows organic vegetables and raises chickens on fields overlooking the mountains, <strong><L to="story-s-nursery">Story's Nursery</L></strong> has been a 35-acre family nursery since 1956, and the <strong><L to="tri-county-farmers-market">Tri-County Farmers' Market</L></strong> runs Thursday evenings. In Greenville, <strong><L to="johnk-family-farm">Johnk Family Farm</L></strong> sells Berkshire pork and grazed beef from a year-round honor stand, and <strong><L to="nocturne-bakehouse">Nocturne Bakehouse</L></strong> leaves naturally leavened sourdough at a self-serve roadside stand — a perfect midday grab.</p>
      <h2 className="trail-h2">Afternoon — maple, honey &amp; the valley town</h2>
      <p>Swing west toward Ashland for <strong><L to="partridge-sugar-house">Partridge Sugar House</L></strong>, a fifth- and sixth-generation maple operation that's been making Catskill Mountain syrup since 1898 — roughly 2,500 taps, wood-fired, no chemical defoamers. Back toward the valley floor in Acra, <strong><L to="the-hen-and-the-hive">The Hen and The Hive</L></strong> is a homestead farm store with honey, pasture eggs, maple, hot sauce, and handmade soap.</p>
      <p>End the day in Cairo, the valley's hub. <strong><L to="old-factory-brewing">Old Factory Brewing</L></strong> pours 17 beers in a renovated bottling plant — plus spirits from its own distillery — with a family-friendly menu and live music, and <strong><L to="see-and-be-kitchen">See and Be Kitchen</L></strong> bakes long-fermentation sourdough and croissants right on Main Street.</p>
      <h2 className="trail-h2">If you've got more time</h2>
      <ul className="trail-list">
        <li><strong>Over the Albany line.</strong> Just north, <strong><L to="heather-ridge-farm-bees-knees-cafe">Heather Ridge Farm &amp; Bees Knees Café</L></strong> in Preston Hollow does a Saturday farm lunch with its own grass-fed meats and wool goods, <strong><L to="kuhar-family-farm">Kuhar Family Farm</L></strong> in Rensselaerville serves weekend brunch near the Huyck Preserve and its waterfall, and <strong><L to="eight-mile-creek-farm">Eight Mile Creek Farm</L></strong> in Westerlo is a certified-organic CSA and nursery. Rensselaerville itself is a storybook historic hamlet much like Oak Hill.</li>
        <li><strong>East toward the river.</strong> Around Climax, <strong><L to="boehm-farm">Boehm Farm</L></strong> has grown apples since 1903 (U-pick, cider donuts, wagon rides), <strong><L to="schnare-s-sunset-orchard">Schnare's Sunset Orchard</L></strong> does U-pick too, and <strong><L to="brewery-lahoff">Brewery LaHoff</L></strong> brews in a 1900 fruit-packing barn. In Earlton, <strong><L to="gray-willow">Gray Willow</L></strong> is a from-scratch brewpub with serious comfort food, and <strong><L to="hbt-family-farm">HBT Family Farm</L></strong> sells heritage-breed pork and beef.</li>
        <li><strong>For foragers.</strong> <strong><L to="wild-hudson-valley">Wild Hudson Valley</L></strong> in Cairo runs a forest farm with mushroom and wild-plant tours.</li>
      </ul>
      <h2 className="trail-h2">A few practical notes</h2>
      <p>This is real working-farm country, which means a lot of small honor-system stands and pre-order bakeries with their own rhythms — the joy of it is the back-road discovery, but call ahead or check social media for current days and hours before you count on any single stop. U-pick (East Durham Farms, Boehm) peaks in late summer and fall, and Partridge is liveliest in spring sugaring season. The valley sits just below the mountaintop, so it pairs naturally with the Almanac's Mountaintop guide if you want to climb into Windham and Hunter afterward. With a couple of breweries and a distillery in the mix, bring a designated driver.</p>
      <p className="trail-crosslinks">The full Greene County lineup is on the Almanac: <strong><Link to="/county/greene/food">farms &amp; food</Link></strong> and <strong><Link to="/county/greene/markets">markets</Link></strong>.</p>
      <p className="trail-close">A hamlet the years forgot, an eighth-generation farm, a sugarhouse older than the cars on the road — one very good Saturday.</p>
    </>
  ),
  "a-saturday-around-coxsackie-and-new-baltimore": () => (
    <>
      <p className="trail-lede">Where Greene County meets the Hudson, a string of old river villages — New Baltimore, Coxsackie, and Athens — sits on the water with the Catskills at their backs. These are working riverfronts that have quietly come back to life: restored 19th-century main streets, a sunset over the river, multi-generation farms just inland, and a couple of farm breweries in old fruit-packing barns. It's a river-towns-and-orchard day more than a tight farm loop, and it makes a lovely, low-key Saturday. Here's a run down the river and a little ways inland.</p>
      <h2 className="trail-h2">Morning — Coxsackie's waterfront</h2>
      <p>Start in Coxsackie, whose restored Reed Street district runs right down to Riverside Park and the Hudson. The <strong><L to="coxsackie-general-store">Coxsackie General Store</L></strong> is a good first stop for coffee and provisions in the historic waterfront, and just up the way, <strong><L to="coxsackie-bee-goods">Coxsackie Bee Goods</L></strong> — based at the half-century-old Twin Spruce Apiary — sells pure Catskill honey, beeswax candles, and herbal goods. If you're here on a Wednesday evening rather than a Saturday, the <strong><L to="coxsackie-farmers-market">Coxsackie Farmers' Market</L></strong> sets up under the pavilion at Riverside Park with panoramic river views, live music, and food trucks. Save room: <strong><L to="coxsackie-creamery">Coxsackie Creamery</L></strong> scoops small-batch ice cream right on the waterfront.</p>
      <p>From here, the short drive north to New Baltimore is worth it for its own sake — a quiet, historic riverside hamlet strung along the Hudson, the kind of place that rewards an unhurried look even without a single stop on the list.</p>
      <h2 className="trail-h2">Late morning — Athens</h2>
      <p>Head south along the river to Athens, another restored waterfront village, with the Hudson-Athens Lighthouse standing offshore and a riverfront park made for a stroll. In the village, <strong><L to="vernon-street-farm">Vernon Street Farm</L></strong> runs a Saturday-morning stand with all-natural produce and a specialty in Asian vegetables, and <strong><L to="night-school-athens">Night School</L></strong> — in the former Crossroads brewpub space on the waterfront — pours local beer and wine alongside pizza by the slice, an easy lunch.</p>
      <p>The farms around Athens run deep. <strong><L to="rexcroft-farm">Rexcroft Farm</L></strong> is a seventh-generation operation on the Leeds-Athens Road growing more than 250 varieties of vegetables, fruits, and meats, and <strong><L to="sunny-acres-farm">Sunny Acres Farm</L></strong> is a six-generation NYS Century Farm dating to 1897, selling pastured eggs and goat. For a one-stop destination, <strong><L to="black-horse-farms">Black Horse Farms</L></strong> on Route 9W is a year-round market with 42 greenhouses, a full garden center, a country store of local honey and maple, and the Mormor's Kitchen bakery turning out pies and breads from scratch.</p>
      <h2 className="trail-h2">Afternoon — inland to the orchards and breweries</h2>
      <p>Turn inland toward Climax and Earlton, where the river plain gives way to orchard country. <strong><L to="boehm-farm">Boehm Farm</L></strong> has grown apples since 1903 — U-pick apples, peaches, and cherries, homemade cider donuts, and horse-drawn wagon rides in the fall — and <strong><L to="schnare-s-sunset-orchard">Schnare's Sunset Orchard</L></strong> does U-pick from July into December. For a pint, <strong><L to="brewery-lahoff">Brewery LaHoff</L></strong> brews in a picturesque 1900 fruit-packing barn, and <strong><L to="gray-willow">Gray Willow</L></strong> in Earlton is a from-scratch brewpub built by two veteran restaurant families, with ten house beers and seriously good comfort food (the rabbit stew and disco fries have a following). Nearby, <strong><L to="hbt-family-farm">HBT Family Farm</L></strong> sells heritage-breed pork and beef, and <strong><L to="nanas-sourdough-treats">Nana's Sourdough Treats</L></strong> keeps a weekend farmstand in Climax.</p>
      <h2 className="trail-h2">If you've got more time</h2>
      <ul className="trail-list">
        <li><strong>Hannacroix and the back roads.</strong> <strong><L to="berkshire-view-farm">Berkshire View Farm</L></strong> does custom meat processing, and <strong><L to="fox-farm-apiary">Fox Farm Apiary</L></strong> — run by a Cornell Master Beekeeper who keeps hives at Olana and area land trusts — sells honey. The Hannacroix Ravine Preserve nearby is a quiet spot for a walk.</li>
        <li><strong>Makers and flowers.</strong> <strong><L to="images-in-wood">Images in Wood</L></strong> in West Coxsackie creates fine marquetry from Catskill hardwoods, and <strong><L to="doodlebug-flower-farm">Doodlebug Flower Farm</L></strong> in Athens grows a chemical-free cut-flower CSA.</li>
        <li><strong>Farm food, delivered.</strong> <strong><L to="field-goods">Field Goods</L></strong>, based in Athens, runs a year-round local-food subscription sourcing from Hudson Valley farms — a good way to keep the valley's produce coming after the trip.</li>
        <li><strong>In December.</strong> <strong><L to="veeder-s-tree-farm">Veeder's Tree Farm</L></strong> in Earlton is a 20-acre choose-and-cut Christmas tree farm with 20,000 trees and handmade wreaths.</li>
      </ul>
      <h2 className="trail-h2">A few practical notes</h2>
      <p>A scheduling heads-up: Coxsackie's market is a Wednesday evening, not a Saturday, so plan the village stops around the waterfront itself if you're here on a weekend. New Baltimore is a scenic detour without listed stops — go for the river views, not the shopping. The orchards and U-pick (Boehm, Schnare's) peak in late summer and fall, and the inland Climax/Earlton stops sit between this loop and the Almanac's Oak Hill guide, so the two pieces stitch together nicely if you want a bigger day. With two breweries on the route, bring a designated driver.</p>
      <p className="trail-crosslinks">The full Greene County lineup is on the Almanac: <strong><Link to="/county/greene/food">farms &amp; food</Link></strong> and <strong><Link to="/county/greene/markets">markets</Link></strong>.</p>
      <p className="trail-close">Three river villages, a seventh-generation farm, ice cream over the Hudson at sunset — one very good Saturday.</p>
    </>
  ),
  "a-saturday-in-columbia-county": () => (
    <>
      <p className="trail-lede">You could spend a whole Saturday in Columbia County and never once reach for something that wasn't grown, fermented, or distilled within a few miles of where you're standing. The county is small enough to cross in under an hour and dense enough with farm distilleries, family wineries, and barn breweries that the hard part isn't finding stops — it's choosing which ones to leave for next time.</p>
      <p>Here's one day that holds together: a loop down the Route 9 river corridor and back through Hudson, anchored by a hilltop lunch. Bring someone who's happy to drive, take your time, and call ahead where you can — these are working farms and small tasting rooms, and hours shift with the season.</p>
      <h2 className="trail-h2">Morning — start on Route 9</h2>
      <p>Begin in the county's southwest corner, where Route 9 runs the western edge of Columbia County a stone's throw from the river.</p>
      <p><strong><L to="hudson-valley-distillers">Hudson Valley Distillers</L> — Clermont.</strong> Two couples, college friends turned distilling partners, started this family farm distillery around 2014 and make their spirits from all-local fruits and grains. They took Best in Class Vodka at the American Distilling Institute's 2016 expo. The tasting room has a proper cocktail program, which makes it a gentle, civilized way to open the day rather than diving straight into flights.</p>
      <p><strong><L to="tousey-winery">Tousey Winery</L> — Germantown.</strong> A few minutes up Route 9, this boutique family winery leans into the cool-climate varieties that actually suit this region instead of fighting it. The tasting room is a relaxed spot to pair a glass with a little food, and it's a stop on the Hudson Berkshire Beverage Trail if you want to keep collecting.</p>
      <h2 className="trail-h2">Midday — lunch on the hill</h2>
      <p><strong><L to="klocke-estate">Klocke Estate</L> — Claverack.</strong> This is the centerpiece. Klocke sits on 160-plus acres atop a Claverack hillside about five miles from Hudson, with views that run clear to the Catskills. It's an earth-to-glass brandy and vermouth distillery with its own vineyards and orchards, distilling in a copper pot still imported from Cognac and aging in French oak inside a timber-framed chai. The name is Middle Dutch for "clock" — a nod to the patience good brandy demands. There's a seasonal à-la-carte restaurant on site, which makes this your lunch and your most memorable tasting in one stop. Reserve ahead.</p>
      <h2 className="trail-h2">Afternoon — cooperage and a cold one</h2>
      <p><strong><L to="olde-york-farm-distillery-cooperage">Olde York Farm Distillery &amp; Cooperage</L> — Claverack.</strong> Still in Claverack, and worth it for the rare thing it does: Olde York makes its own barrels in an on-site cooperage, one of the few in the eastern United States. They distill whiskeys, gins, vodkas, and seasonal liqueurs from New York grain and fruit (it's also home to Cooper's Daughter Spirits). Take the tour if it's running — watching barrels get built is not something most beverage trails can offer.</p>
      <p><strong><L to="suarez-family-brewery">Suarez Family Brewery</L> — Hudson.</strong> Wind down with beer. Dan and Taylor Suarez run what's widely called one of the best pilsner-focused breweries in the country — a deliberate zag away from the high-ABV, hop-bomb era toward dialed-in lagers, country ales, and what they cheerfully call "other crispy little beers," often made with local farm ingredients. Long shared tables, no pretense. A clean, quiet finish to a full day.</p>
      <h2 className="trail-h2">If you've still got it in you</h2>
      <p>That's a complete day, but it barely scratches the county. Save these for the next trip:</p>
      <ul className="trail-list">
        <li><strong><L to="hillrock-estate-distillery">Hillrock Estate Distillery</L> — Ancram.</strong> The first U.S. distillery since before Prohibition to floor-malt and hand-craft whiskey on-site from its own grain, and home to a Solera-aged bourbon. Tours by reservation.</li>
        <li><strong><L to="chatham-brewing">Chatham Brewing</L> — Chatham.</strong> Named Best Craft Brewery in the Hudson Valley in both 2015 and 2017, with a new experimental beer every month.</li>
        <li><strong><L to="sloop-brewing-at-the-barn">Sloop Brewing @ The Barn</L> — Elizaville.</strong> Where the Juice Bomb IPA was born. Drink one on the grass.</li>
        <li><strong><L to="hudson-chatham-winery">Hudson-Chatham Winery</L> — Ghent.</strong> Columbia County's first winery, opened in 2007, and a repeat Best Local Winery.</li>
        <li><strong><L to="little-apple-cidery">Little Apple Cidery</L> — Hillsdale.</strong> Small-batch organic cider from heirloom apples on two restored NOFA-NY certified orchards.</li>
      </ul>
      <h2 className="trail-h2">A few practical notes</h2>
      <p>Pace yourself and bring a designated driver — this is a tasting day, not a drinking one. Many of these are working farms with seasonal or weekend-only tasting hours, so a quick call ahead saves a wasted drive. And if you want to build a picnic instead of (or alongside) the Klocke lunch, Hudson has you covered: pick up award-winning local cheese from <strong><L to="mcgrath-cheese-company-2">McGrath Cheese Company</L></strong> and round it out at <strong><L to="rolling-grocer-19">Rolling Grocer 19</L></strong>, the worker-owned co-op on South 2nd Street.</p>
      <p className="trail-crosslinks">The full list of Columbia County's licensed makers — every distillery, winery, brewery, and cidery in the directory — lives here: <strong><Link to="/county/columbia/craftbeverages">hudsonvalleyalmanac.com/county/columbia/craftbeverages</Link></strong>.</p>
      <p className="trail-close">One county. One very good Saturday.</p>
    </>
  ),
  "a-saturday-in-cooperstown-and-otsego-county": () => (
    <>
      <p className="trail-lede">At the headwaters of the Susquehanna, where Otsego Lake — James Fenimore Cooper's "Glimmerglass" — stretches north from the village, Cooperstown draws visitors for baseball and ends up keeping them for everything else: a legendary Belgian brewery on an old hop farm, the nation's reigning best cidery, a year-round farmers market, and a deep bench of working farms, including a pocket of Amish organic dairies. This is the farthest-flung county in these guides — genuinely central New York — but for a farm-and-village day it's hard to beat. Here's a Saturday in and around Cooperstown.</p>
      <h2 className="trail-h2">Morning — Cooperstown village</h2>
      <p>Start at the <strong><L to="cooperstown-farmers-market">Cooperstown Farmers' Market</L></strong>, a year-round indoor market in Pioneer Alley off Main Street, running since 1991 — 30-plus farmers and makers all from within 50 miles, with live music every Saturday and Double Up Food Bucks matching. The vendor list alone is a tour of the county: pastured meats, artisan cheese, maple, honey, and fiber. While you're on Main Street, the Baseball Hall of Fame needs no introduction, and <strong><L to="cooperstown-distillery">Cooperstown Distillery</L></strong> pours small-batch spirits with names that nod to the village's two obsessions — Beanball Bourbon, Doubleday Vodka, Glimmerglass Vodka. <strong><L to="cooperstown-natural-foods">Cooperstown Natural Foods</L></strong> is a good organic grocery stop for the road.</p>
      <h2 className="trail-h2">Late morning — Fly Creek</h2>
      <p>Three miles out, <strong><L to="fly-creek-cider-mill-orchard">Fly Creek Cider Mill &amp; Orchard</L></strong> is a water-powered mill pressing cider on its original 1856 equipment — named the Nation's Best Cidery by USA Today in 2024 — with a sprawling Mill Store of sharp cheddar, fudge, and farm goods, plus a Snack Barn for lunch and a duck pond the kids will not leave. On the same grounds, the <strong><L to="fly-creek-cider-mill-farm-winery">Fly Creek Cider Mill Farm Winery</L></strong> offers tastings of hard ciders, apple wines, and spirits over the millpond. Also in Fly Creek, the <strong><L to="cooperstown-bat-company">Cooperstown Bat Company</L></strong> has been turning New York ash and maple into baseball bats since 1981, with factory tours.</p>
      <h2 className="trail-h2">Midday — the brewery trail</h2>
      <p>Just south of the village (technically in Milford) sits <strong><L to="brewery-ommegang">Brewery Ommegang</L></strong>, one of the country's great Belgian-style breweries — founded in 1997 on a 136-acre former hop farm, home of Three Philosophers and Hennepin, with the 100-seat Café Ommegang, daily tours, and a summer concert series. Next door, <strong><L to="council-rock-brewery">Council Rock Brewery</L></strong> brews with 100% New York ingredients alongside a farm-to-table menu, and <strong><L to="red-shed-brewing-cooperstown">Red Shed Brewing</L></strong> rounds out the Cooperstown Beverage Trail with 20 taps and food trucks. (A designated driver makes this stretch a lot more fun.)</p>
      <h2 className="trail-h2">Afternoon — the orchard and the Amish dairy country</h2>
      <p>For the farm heart of the county, head to <strong><L to="middlefield-orchard">Middlefield Orchard</L></strong>, a 130-acre fruit farm with 10,000 apple trees — U-pick berries and 20-plus apple varieties from July through October, plus pumpkins and hayrides in fall. Then drive north toward Richfield Springs, where a cluster of Amish and organic dairies makes some of the best food in central New York. <strong><L to="mountain-view-dairy">Mountain View Dairy</L></strong> is an Amish-run certified-organic grass-fed dairy with raw milk, farmstead cheese, and a farm store open Monday through Saturday; <strong><L to="byler-farm">Byler Farm</L></strong> makes raw cow's-milk cheeses and cheese curds; and <strong><L to="ortensi-farm">The Ortensi Farm</L></strong> has been certified organic since 2006, raising grass-finished beef and growing organic potatoes and garlic. For goat cheese, <strong><L to="painted-goat-farm">Painted Goat Farm</L></strong> in Garrattsville runs a solar-powered dairy.</p>
      <h2 className="trail-h2">If you've got more time</h2>
      <ul className="trail-list">
        <li><strong>On the water.</strong> <strong><L to="canoe-kayak-rentals-and-sales">Canoe &amp; Kayak Rentals</L></strong> has put-ins on the Susquehanna, Goodyear Lake, and Otsego Lake itself — including at Glimmerglass State Park on the lake's north end. Paddling the Glimmerglass is the quintessential Cooperstown afternoon.</li>
        <li><strong>More farms and markets.</strong> <strong><L to="weaver-s-farm-market">Weaver's Farm Market</L></strong> in Morris is a 4,000-square-foot Amish market carrying goods from 60-plus local producers, <strong><L to="chicory-creek-farm">Chicory Creek Farm</L></strong> in Mount Vision is a long-established certified-organic operation, and the <strong><L to="oneonta-farmers-market">Oneonta Farmers' Market</L></strong> has run for over 50 years at the county's southern end.</li>
        <li><strong>Sweets and flowers.</strong> <strong><L to="mill-hollow-maple">Mill Hollow Maple</L></strong> taps 6,000 trees for organic syrup, <strong><L to="straight-from-the-hive-2">Straight from the Hive</L></strong> sells raw honey in Cherry Valley, and <strong><L to="misty-meadows-flower-farm">Misty Meadows Flower Farm</L></strong> grows chemical-free cut flowers there too.</li>
        <li><strong>A look ahead.</strong> <strong><L to="unadilla-community-farm">Unadilla Community Farm</L></strong> in West Edmeston is an off-grid permaculture education center with a food forest of 350-plus fruit and nut trees.</li>
      </ul>
      <h2 className="trail-h2">A few practical notes</h2>
      <p>The Cooperstown market is year-round and indoors (Saturdays, plus Tuesdays in summer), which makes it a reliable anchor in any season — though Cooperstown itself is busiest in summer when the Hall of Fame and the lake are in full swing. The Amish farm stores around Richfield Springs keep their own hours and are cash-friendly; call with patience, as some phones are in an outdoor shed. This is the longest drive of any guide here — closer to the Mohawk Valley than the Hudson — so it's a full day or an overnight, not a quick hop.</p>
      <p className="trail-crosslinks">The full Otsego lineup is on the Almanac: <strong><Link to="/county/otsego/food">farms &amp; food</Link></strong> and <strong><Link to="/county/otsego/craftbeverages">craft beverages</Link></strong>.</p>
      <p className="trail-close">A lake called Glimmerglass, the best cider in the country, an Amish dairy down a back road — one very good Saturday.</p>
    </>
  ),
  "a-saturday-in-kingston-and-the-catskill-foothills": () => (
    <>
      <p className="trail-lede">This corner of Ulster County trades farm stands for something else: New York's first capital, a string of arts-minded river and mountain towns, a reservoir ringed by the Catskill High Peaks, and a dense run of makers, brewers, and cider folk. It's less a farm loop than a Hudson-river-towns-and-foothills day — but it's one of the most rewarding drives in the region, and it's anchored by Kingston, a historic city that's become one of the Hudson Valley's most creative. Here's a loop from Kingston out into the Catskill foothills and back.</p>
      <h2 className="trail-h2">Morning — historic Kingston</h2>
      <p>Start in Kingston, which wears its history on its sleeve. The uptown Stockade District is the oldest neighborhood, a walkable grid of 17th- and 18th-century stone houses, while down the hill the Rondout waterfront meets the Hudson, with the Maritime Museum and a clutch of good restaurants. Kingston's Saturday farmers market is a strong morning stop if your timing lines up.</p>
      <p>For makers, the <strong><L to="yarn-farm-kingston">Yarn Farm</L></strong> in the Rondout is a bright, welcoming fiber-arts shop, and <strong><L to="milestone-mill">Milestone Mill</L></strong> stone-grinds local organic grain from the Hudson Valley Farm Hub into flour, cornmeal, and tortillas (find them at the market). If beer's on your mind for later, <strong><L to="keegan-ales">Keegan Ales</L></strong> — one of Ulster's oldest breweries, home of the Mother's Milk stout — and <strong><L to="kingston-standard-brewing">Kingston Standard Brewing</L></strong> are both in town.</p>
      <h2 className="trail-h2">Late morning — Saugerties</h2>
      <p>Head north to Saugerties, a handsome village full of antiques and independent shops. It's maker country: <strong><L to="tivoli-tile-works">Tivoli Tile Works</L></strong> throws handmade dinnerware, <strong><L to="martin-keith-guitars">Martin Keith Guitars</L></strong> builds custom instruments from local tonewoods, and <strong><L to="catskill-mountain-moonshine">Catskill Mountain Moonshine</L></strong> pours corn whiskey and small-batch spirits (call ahead — the tasting room hours move). For a stroll, the village's Hudson River lighthouse and the bluestone sculpture park just outside town are both local landmarks worth the detour.</p>
      <h2 className="trail-h2">Midday — Woodstock</h2>
      <p>Cut west to Woodstock, the arts town that needs no introduction — galleries, the village green, and an easy lunch among the shops. Just outside town, <strong><L to="abandoned-hard-cider">Abandoned Hard Cider</L></strong> makes nuanced ciders from foraged and wild apples — rare heirlooms like Esopus Spitzenburg and Golden Russet rescued from abandoned Catskill orchards. It's a homesteader's cider with real depth.</p>
      <h2 className="trail-h2">Afternoon — the Ashokan</h2>
      <p>The scenic centerpiece of the day is the Ashokan Reservoir, where the Catskill High Peaks reflect in the water and the <strong>Ashokan Rail Trail</strong> runs flat and paved for miles along the shoreline — one of the great easy walks or bike rides in the region (check the trail's current rules before you go). Nearby in Olivebridge, the <strong><L to="ashokan-center">Ashokan Center</L></strong> is a 385-acre education and retreat center on the National Register, with an 1885 covered bridge over the Esopus and a deep musical history — it's the place that inspired the fiddle tune "Ashokan Farewell," and it hosts the beloved Summer and Winter Hoot festivals.</p>
      <h2 className="trail-h2">Late afternoon — Phoenicia</h2>
      <p>Follow Route 28 up into the mountains to Phoenicia, a tiny Esopus Creek village (and summer tubing destination). <strong><L to="woodstock-brewing">Woodstock Brewing</L></strong> has a taproom and beer garden here in a converted industrial space, with hop-forward ales and bench-style outdoor seating — a fine place to end the day. <strong><L to="phoenicia-honey-co-2">Phoenicia Honey Co.</L></strong> makes small-batch honey and bath goods that celebrate the wild Catskills.</p>
      <h2 className="trail-h2">If you've got more time</h2>
      <ul className="trail-list">
        <li><strong>More Kingston farming.</strong> <strong><L to="seed-song-farm-center">Seed Song Farm &amp; Center</L></strong> is a community farm and education center right in the city, and the <strong><L to="hudson-valley-farm-hub-agricultural-education">Hudson Valley Farm Hub</L></strong> in Hurley anchors the region's organic grain and farmer-training work.</li>
        <li><strong>Herbs and bees.</strong> <strong><L to="herban-cura-plants-to-the-people">Herban Cura</L></strong> in West Saugerties is a regenerative herb farm and herbalism school at the foot of the mountains, and <strong><L to="urban-apis">Urban Apis</L></strong> in Hurley sells raw honey from a hive-first apiary.</li>
        <li><strong>For native plants.</strong> The <strong><L to="ulster-county-native-nursery">Ulster County Native Nursery</L></strong> in Ulster Park grows pesticide-free host and pollinator plants.</li>
        <li><strong>A good cause and a famous owl.</strong> The <strong><L to="ravensbeard-wildlife-center">Ravensbeard Wildlife Center</L></strong> near Saugerties — which rehabbed "Rockefeller," the owl found in the 2020 Rockefeller Center tree — runs on donations and education.</li>
      </ul>
      <h2 className="trail-h2">A few practical notes</h2>
      <p>This slice of Ulster is heavier on towns, makers, and beverages than on farm stands, so I've leaned into what's actually here — the Ashokan and the arts towns carry the day. The reservoir's rail trail is the scenic must-do; it's flat and easy, but confirm the current trail rules (including whether dogs are allowed) before you set out. Kingston's farmers market runs Saturdays. And with breweries, a cidery, and a distillery on the route, bring a designated driver.</p>
      <p className="trail-crosslinks">The full Ulster lineup is on the Almanac: <strong><Link to="/county/ulster/craftbeverages">Ulster County craft beverages</Link></strong> and <strong><Link to="/county/ulster/artisan">makers &amp; artisans</Link></strong>.</p>
      <p className="trail-close">A first capital, an arts town or two, a reservoir under the High Peaks — one very good Saturday.</p>
    </>
  ),
  "a-saturday-in-lake-george": () => (
    <>
      <p className="trail-lede">At the northern edge of the region, where the Hudson Valley gives way to the Adirondacks, Warren County is built around one of the most famous lakes in the Northeast. This is more a lake-and-craft-beverage day than a farm loop — the farm stands thin out as the mountains rise — but it has a year-round market, one of the Adirondacks' best cheesemakers, a remarkable concentration of maple sugarhouses, and a string of breweries and distilleries with the lake as a backdrop. Here's a day from Glens Falls up the shore of Lake George, with the Warrensburg cheese-and-maple country waiting just inland.</p>
      <h2 className="trail-h2">Morning — Glens Falls</h2>
      <p>Start in Glens Falls, a walkable small city with a surprisingly good food scene. The <strong><L to="glens-falls-farmers-market">Glens Falls Farmers Market</L></strong> runs Saturdays at the South Street Pavilion — and, unusually for the region, year-round, indoors through the winter — with local produce, meat, dairy, maple, and makers. Grab a loaf from <strong><L to="rock-hill-bakehouse">Rock Hill Bakehouse</L></strong>, a renowned artisan bakery turning out naturally leavened, hearth-baked bread. For a fun stop, <strong><L to="coopers-cave-ale-company">Cooper's Cave Ale Company</L></strong> is a family brewery whose taproom doubles as an old-fashioned soda fountain and ice cream parlor — named for the cave James Fenimore Cooper used in *The Last of the Mohicans*.</p>
      <h2 className="trail-h2">Late morning — Lake George Village</h2>
      <p>Drive north to Lake George Village, right on the water — beaches, steamboat cruises, and the lake itself stretching off into the mountains. The village is a tidy cluster of tasting rooms: the <strong><L to="adirondack-pub-and-brewery">Adirondack Pub &amp; Brewery</L></strong> brews 25-plus Adirondack-themed beers in a copper-clad cabin brewery (the Bear Naked Ale is the flagship), <strong><L to="high-peaks-distilling">High Peaks Distilling</L></strong> runs replica copper pot stills for Scottish-influenced whiskey — its CloudSplitter single malt named for Mount Marcy — and <strong><L to="adirondack-winery">Adirondack Winery</L></strong> pours award-winning handcrafted wines. Lunch and a lake view are easy here.</p>
      <h2 className="trail-h2">Midday — up the west shore to Bolton Landing</h2>
      <p>Follow the lake's west shore to Bolton Landing, one of its prettiest stretches. <strong><L to="bolton-landing-brewing">Bolton Landing Brewing</L></strong> has a 7-barrel brewhouse and a big lake-view patio (dog-friendly), and <strong><L to="american-oak-distillery">American Oak Distillery</L></strong> ages bourbon and whiskey in charred oak, passing its used barrels to local maple producers for barrel-aged syrup — its Oak Room tasting room on Lakeshore Drive pours cocktails with the lake right there.</p>
      <h2 className="trail-h2">Afternoon — Warrensburg's cheese and maple country</h2>
      <p>Cut inland to Warrensburg, where the real farm story is. <strong><L to="nettle-meadow-farm-and-cheese-company">Nettle Meadow Farm &amp; Cheese</L></strong> is one of the most acclaimed small-batch cheesemakers in the Adirondacks — spreadable goat and mixed-milk cheeses, washed and bloomy rinds, all from its own herd — with a seasonal farm store, tours, and a popular Cheese and Spirits pairing. The <strong><L to="warrensburgh-riverfront-farmers-market">Warrensburgh Riverfront Farmers Market</L></strong> runs Fridays along the Schroon River, and <strong><L to="bandstand-brew-works">Bandstand Brew Works</L></strong> is a good local stop for a pint.</p>
      <p>This corner is also serious maple country — the hamlet of Thurman has one of the densest concentrations of sugarhouses in the Adirondacks. <strong><L to="toad-hill-maple-farm">Toad Hill Maple Farm</L></strong> has a beautiful timber-frame sugarhouse and offers wagon rides into the sugar bush, <strong><L to="valley-road-maple-farm">Valley Road Maple</L></strong> is an award-winning multi-generation producer, and <strong><L to="hidden-hollow-maple-farm">Hidden Hollow</L></strong> taps over 5,000 trees with a traditional wood-fired evaporator. (Spring, during Maple Weekend, is the time to catch them open.)</p>
      <h2 className="trail-h2">If you've got more time</h2>
      <ul className="trail-list">
        <li><strong>Queensbury, between the two.</strong> <strong><L to="springbrook-hollow-farm-distillery">Springbrook Hollow Farm Distillery</L></strong> makes moonshines and rye on 200 acres with French Mountain views, and <strong><L to="northway-brewing">Northway Brewing</L></strong> sits right on the Route 9 corridor.</li>
        <li><strong>The county's farms.</strong> <strong><L to="landon-hill-estate-farm">Landon Hill Estate Farm</L></strong> in Chestertown is the only certified-organic vegetable farm in Warren County, and <strong><L to="owl-valley-farm">Owl Valley Farm</L></strong> in Pottersville is a hop farm (welcoming visitors) that supplies the region's brewers.</li>
        <li><strong>A free family stop.</strong> The <strong><L to="warren-county-fish-hatchery">Warren County Fish Hatchery</L></strong> in Warrensburg has been raising trout since 1914, with display ponds, a playground, picnic pavilions, and a disc golf course — free to visit.</li>
        <li><strong>Going deeper north.</strong> The <strong><L to="north-creek-farmers-market-2">North Creek Farmers Market</L></strong> at Riverfront Park serves the Gore Mountain community if you're headed up the Hudson.</li>
      </ul>
      <h2 className="trail-h2">A few practical notes</h2>
      <p>This is a tourism region first, so Lake George Village is busiest (and priciest) in high summer — the shoulder seasons are calmer and the foliage drive up the west shore in fall is spectacular. The Glens Falls market is the dependable year-round anchor. Nettle Meadow's farm store is seasonal, and the Thurman sugarhouses are really a spring thing — wonderful during Maple Weekend, quiet otherwise — so call ahead. With this many breweries and distilleries on the route, a designated driver is a must. And if you're coming up from the Battenkill, the Fort Ann distillery and brewery in the Washington County guide drop you right at the lake's doorstep.</p>
      <p className="trail-crosslinks">The full Warren County lineup is on the Almanac: <strong><Link to="/county/warren/craftbeverages">craft beverages</Link></strong> and <strong><Link to="/county/warren/markets">markets</Link></strong>.</p>
      <p className="trail-close">A great lake, a copper still or two, the maple woods behind it — one very good Saturday.</p>
    </>
  ),
  "a-saturday-in-northern-westchester": () => (
    <>
      <p className="trail-lede">Say "Westchester" and most people picture commuter suburbs — but drive north of the parkways and the county turns into genuine horse-and-farm country: rolling hills in North Salem and Bedford, county-run working farms open to the public, the best farmers market around, and Westchester's only cidery. The southern half, along the Hudson, is more of a river-towns-and-breweries scene (and a good one). This guide leans into the rural north, with the river corridor waiting as a second arm. Here's a Saturday up in the hills.</p>
      <h2 className="trail-h2">Morning — Chappaqua &amp; Bedford</h2>
      <p>Start at the <strong><L to="chappaqua-farmers-market">Chappaqua Farmers Market</L></strong>, voted the best in Westchester ten years running — 40-plus vendors right at the Metro-North station on Saturdays, with a winter indoor market keeping it year-round. From there, swing through Bedford Village to <strong><L to="bedford-farms">Bedford Farms</L></strong>, a nine-acre nursery and farm market with a café among the garden beds, growing its own produce and flowers on-site. Beekeeping fans can seek out <strong><L to="out-of-the-hive">Out of the Hive</L></strong> in Bedford Hills, a treatment-free raw-honey producer.</p>
      <h2 className="trail-h2">Late morning — the county farms at Somers &amp; Yorktown</h2>
      <p>Two of the best stops here are owned by the county and free to visit. <strong><L to="muscoot-farm">Muscoot Farm</L></strong> in Somers is a historic interpretive farm with animals, a farm store, and one of Westchester's most beloved markets — the <strong><L to="muscoot-farm-farmers-market">Muscoot Farm Farmers Market</L></strong> runs Sundays, May through November. Nearby, <strong><L to="hilltop-hanover-farm">Hilltop Hanover Farm</L></strong> in Yorktown is a 187-acre working farm and environmental center with a market that donates at least a quarter of its produce to food-access partners. Both are excellent with kids.</p>
      <h2 className="trail-h2">Midday — North Salem's orchard and cider</h2>
      <p>The rural northeast corner around North Salem is the farm heart of the county. <strong><L to="harvest-moon-farm-orchard">Harvest Moon Farm &amp; Orchard</L></strong> is a 65-acre family farm with a year-round store, a seasonal café, U-pick apples and pumpkins, and a big fall harvest festival — and it's home to <strong><L to="hardscrabble-cider">Hardscrabble Cider</L></strong>, Westchester's only cidery, with a cider garden, brick-oven pizza, and live music on summer weekends. It's the natural place for lunch. Close by, <strong><L to="herondale-farm">Herondale Farm</L></strong> raises 100% grass-fed beef and lamb, and <strong><L to="purdy-s-farmer-the-fish">Purdy's Farmer &amp; the Fish</L></strong> offers U-pick and a CSA.</p>
      <h2 className="trail-h2">Afternoon — Yorktown's orchard and maple</h2>
      <p>Round out the day in Yorktown Heights. <strong><L to="wilkens-fruit-fir-farm">Wilkens Fruit &amp; Fir Farm</L></strong> has been at it for over a century — pick-your-own peaches and apples, fresh-pressed cider, cider donuts, and choose-and-cut Christmas trees in December. And <strong><L to="white-oak-farm">White Oak Farm</L></strong> is the last commercial maple producer in Westchester, tapping 2,400 trees, with a sugarhouse, sawmill, and a year-round market. For a craft-beverage finish, the <strong><L to="captain-lawrence-barrel-house">Captain Lawrence Barrel House</L></strong> in Mount Kisco pours sours, stouts, and barrel-aged beers from the county's craft-beer pioneer.</p>
      <h2 className="trail-h2">If you've got more time — the Hudson River corridor</h2>
      <p>The southern, riverside half of the county is a different day — historic river towns and a deep brewery bench:</p>
      <ul className="trail-list">
        <li><strong><L to="captain-lawrence-brewing-company">Captain Lawrence Brewing</L></strong> in Elmsford is the original (a beer hall, garden, and scratch kitchen), with <strong><L to="current-spirits">Current Spirits</L></strong> distilling next door.</li>
        <li><strong><L to="peekskill-brewery">Peekskill Brewery</L></strong> and <strong><L to="river-outpost-brewing">River Outpost</L></strong> anchor the Peekskill waterfront, and <strong><L to="sing-sing-kill-brewery">Sing Sing Kill Brewery</L></strong> revived a pair of abandoned storefronts in downtown Ossining.</li>
        <li><strong><L to="stilltheone-distillery">StilltheOne Distillery</L></strong> in Port Chester makes one of the world's first honey-based vodkas, and <strong><L to="yonkers-brewing-company">Yonkers Brewing</L></strong> sits near the Yonkers waterfront.</li>
        <li>For a great story and a better brownie, <strong><L to="greyston-bakery">Greyston Bakery</L></strong> in Yonkers bakes for Ben &amp; Jerry's and runs a pioneering Open Hiring model — anyone can get a job, no résumé or interview.</li>
      </ul>
      <p>Also worth a detour: <strong><L to="hemlock-hill-farm">Hemlock Hill Farm</L></strong> in Cortlandt (pasture-raised meats, weekend tours), <strong><L to="d-i-g-farm-wild-roots-project">D.I.G. Farm</L></strong> in North Salem (foraging and herbalism workshops), and standout growers like <strong><L to="katonah-nursery">Katonah Nursery</L></strong> and <strong><L to="homegrown-kitchen-gardens">Homegrown Kitchen Gardens</L></strong>, which grows organic starts at Tarrytown's Lyndhurst estate.</p>
      <h2 className="trail-h2">A few practical notes</h2>
      <p>The Chappaqua market is the year-round, every-Saturday anchor — and, like much of lower Westchester, it's a short walk from Metro-North, so the southern brewery-and-river-towns version of this day is very doable car-free. The northern farms, though, are spread across rural townships and really need a car. U-pick at Harvest Moon and Wilkens peaks in fall, and Muscoot's market is Sunday while Chappaqua's is Saturday — so check days before you build the route. With cideries and breweries in the mix, bring a designated driver.</p>
      <p className="trail-crosslinks">The full Westchester lineup is on the Almanac: <strong><Link to="/county/westchester/food">farms &amp; food</Link></strong> and <strong><Link to="/county/westchester/craftbeverages">craft beverages</Link></strong>.</p>
      <p className="trail-close">Horse-country hills, a county farm or two, the only cider press in the county — one very good Saturday.</p>
    </>
  ),
  "a-saturday-in-rockland-county": () => (
    <>
      <p className="trail-lede">Rockland is the smallest and most densely settled county in these guides — squeezed between the Hudson, the New Jersey line, and the New York City suburbs — so this isn't a sprawling farm loop. But it holds some real surprises: the oldest working farm in the county has been in the same family for eleven generations since 1711, a fifth-generation orchard just opened the county's first cidery, the Hudson River arts villages are among the prettiest anywhere, and Harriman's wilderness sits right on the doorstep. Here's a day that pairs a couple of historic farms with the riverfront and the mountains.</p>
      <h2 className="trail-h2">Morning — the river villages</h2>
      <p>Start along the Hudson in Piermont and Nyack, two arts-minded villages with great walking and water views. The <strong><L to="piermont-farmers-market">Piermont Farmers' Market</L></strong> runs year-round on Sundays in the riverfront village, with a strong artisan-food culture — local honey, foraged mushrooms, bread, and the Concklin orchard among the vendors — and the Piermont Pier stretching out into the river is a fine place to stretch your legs. Just up the road, the <strong><L to="nyack-farmers-market">Nyack Farmers' Market</L></strong> anchors a lively village of shops and cafés beneath the Mario Cuomo Bridge. For herbal goods, Piermont has an outpost of the iconic East Village herbalist <strong><L to="flower-power-herbs-roots">Flower Power Herbs &amp; Roots</L></strong>, and Nyack has <strong><L to="sage-s-herbal-apothecary">Sage's Herbal Apothecary</L></strong>.</p>
      <h2 className="trail-h2">Midday — the historic orchards</h2>
      <p>Head inland to Rockland's farm heart. <strong><L to="the-orchards-of-concklin">The Orchards of Concklin</L></strong> in Pomona is the oldest working farm in the county and one of the oldest family businesses in New York State — farmed by eleven generations of Concklins since 1711, with U-pick apples, a year-round farm stand, and cider donuts and pies worth the trip alone. Nearby in Congers, <strong><L to="dr-davies-farm">Dr. Davies Farm</L></strong> is a fifth-generation farm founded in 1891 by one of New York's first female physicians — apples, peaches, a daily farm stand, and apple and pumpkin picking among 4,000 trees. On its grounds, <strong><L to="red-barn-cidery">Red Barn Cidery</L></strong> is Rockland's first farm-to-glass cidery, with an outdoor taproom overlooking the orchard and live music Thursday through Sunday — an ideal lunch-and-cider stop. Families should note <strong><L to="west-maple-farm">West Maple Farm</L></strong> in Monsey, a 15-acre farm with a petting zoo, hayrides, honeybee tours, and pick-your-own vegetables.</p>
      <h2 className="trail-h2">Afternoon — wine country and the mountains</h2>
      <p>For a glass of something local, <strong><L to="torne-valley-vineyards">Torne Valley Vineyards</L></strong> in Hillburn is the first winery in Rockland County — a restored 19th-century estate on the Ramapo River pouring wine by the glass or bottle, just 40 miles from Manhattan. And just beyond it lies Harriman State Park, the second-largest in the state: lakes, miles of trails, and genuine forest at the county's western edge. If you're gearing up for the outdoors, <strong><L to="davis-sport-shop">Davis Sport Shop</L></strong> in Sloatsburg sits right at Harriman's doorstep.</p>
      <h2 className="trail-h2">If you've got more time</h2>
      <ul className="trail-list">
        <li><strong>The breweries.</strong> <strong><L to="district-96-beer-factory">District 96 Beer Factory</L></strong> in New City is known across the valley for its hazy IPAs, <strong><L to="gentle-giant-brewing-company">Gentle Giant Brewing</L></strong> anchors downtown Pearl River with house-made pizza, and <strong><L to="stony-point-brewing-company">Stony Point Brewing</L></strong> runs a German-themed Bierhaus in West Haverstraw.</li>
        <li><strong>More farms and markets.</strong> <strong><L to="threefold-community-farm">Threefold Community Farm</L></strong> in Chestnut Ridge is a long-established biodynamic farm, the <strong><L to="pearl-river-farmers-market">Pearl River Farmers' Market</L></strong> runs Saturdays, and the <strong><L to="haverstraw-farmers-market">Haverstraw Farmers' Market</L></strong> serves the north county on Sundays.</li>
        <li><strong>Makers and growers.</strong> <strong><L to="the-stitchery">The Stitchery</L></strong> in Pearl River has been a beloved yarn shop for 40 years, <strong><L to="captured-in-glass">Captured in Glass</L></strong> does stained glass in Stony Point, and <strong><L to="down-to-earth-living-rockland-wholesale-nursery">Down to Earth Living</L></strong> in Pomona is the county's largest nursery. For raw honey, <strong><L to="rockland-honey-2">Rockland Honey</L></strong> keeps hives across the county.</li>
      </ul>
      <h2 className="trail-h2">A few practical notes</h2>
      <p>A scheduling heads-up: several of Rockland's markets — Piermont and Haverstraw — run on Sundays, while Pearl River is Saturday, so check the day before you build the route. The river villages of Nyack and Piermont are reachable by bus from the city, but the orchards, the winery, and Harriman all need a car. U-pick at Concklin and Davies peaks in the fall, when the cidery and the orchards are at their liveliest. And with a winery, a cidery, and several breweries on the map, plan for a designated driver.</p>
      <p className="trail-crosslinks">The full Rockland lineup is on the Almanac: <strong><Link to="/county/rockland/food">farms &amp; food</Link></strong> and <strong><Link to="/county/rockland/markets">markets</Link></strong>.</p>
      <p className="trail-close">A farm older than the country, a riverfront village, a mountain park at the edge of the suburbs — one very good Saturday.</p>
    </>
  ),
  "a-saturday-in-saratoga": () => (
    <>
      <p className="trail-lede">Saratoga Springs is the rare destination where you can spend a whole day on foot and still call it a farm trip. The mineral springs that made the town famous, a grand state park, a walkable Broadway, a community farm right in the middle of it all, and a brewery bench as deep as anywhere in the state — it's the urbane counterpoint to the rural loops in this series. Here's a day built around the Spa City, with the farm country of Saratoga County waiting at the edges.</p>
      <h2 className="trail-h2">Morning — the state park and the market</h2>
      <p>Start in Saratoga Spa State Park, a National Historic Landmark of grand bathhouses, mineral springs, and shaded paths. On Sundays, the <strong><L to="spa-city-farmers-market">Spa City Farmers' Market</L></strong> sets up here year-round — inside the landmark Lincoln Baths in winter, out on Warming Hut Field in summer — with around 50 vetted local producers, live music, and free parking. (Any other day, the <strong><L to="saratoga-farmers-market-2">Saratoga Farmers Market</L></strong> runs its own downtown markets through the week.) Stroll the park, taste the famous spring water, and get your bearings.</p>
      <p>Then head to <strong><L to="pitney-meadows-community-farm">Pitney Meadows Community Farm</L></strong>, a nonprofit community farm right in Saratoga Springs, open dawn to dusk every day of the year, with a 24/7 honor-system farm stand of just-harvested produce and public trails to walk off breakfast. It's a genuinely lovely thing to have inside a city.</p>
      <h2 className="trail-h2">Midday — Broadway and a brewpub lunch</h2>
      <p>Walk Broadway and the surrounding historic district — shops, the springs in Congress Park, the architecture — and pick a brewpub for lunch. <strong><L to="druthers-brewing-saratoga-springs">Druthers Brewing</L></strong> is tucked just off Broadway behind an iron gate with a popular beer garden and a World Beer Cup–winning Scottish ale. <strong><L to="walt-whitman-brewing">Walt &amp; Whitman Brewing</L></strong> occupies the old *Saratogian* newspaper building and doubles as a coffeehouse. Or, a little out from the center on Maple Avenue, <strong><L to="artisanal-brew-works">Artisanal Brew Works</L></strong> pours 20 beers beside a full bistro and one of the city's largest outdoor terraces, with direct access to Palmertown Range trails.</p>
      <h2 className="trail-h2">Afternoon — the farm brewery</h2>
      <p>For the agricultural heart of the day, drive a few minutes north to Moreau and <strong><L to="dancing-grain-farm-brewery">Dancing Grain Farm Brewery</L></strong> — Saratoga County's only true farm brewery, 100% women-owned, growing more than 90% of its own ingredients on a second-generation family farm. The barley, rye, wheat, and even the yeast cultures come off the land itself; the brewpub looks out over the grain fields, and there's a sunflower festival each summer. It's field-to-glass in the most literal sense, and it's the stop that ties the day's theme together.</p>
      <h2 className="trail-h2">Late afternoon — makers and a tasting</h2>
      <p>The county's makers are worth a detour. The <strong><L to="saratoga-clay-arts-center">Saratoga Clay Arts Center</L></strong> in Schuylerville is a 13,000-square-foot ceramics center with a gallery worth browsing, and the <strong><L to="general-bailey-homestead-farm">General Bailey Homestead Farm</L></strong> in Greenfield Center — a working farm since 1798 — sells hand-dyed wool yarn from its own flock.</p>
      <p>To finish with a tasting, <strong><L to="saratoga-courage-distillery">Saratoga Courage Distillery</L></strong> in Round Lake makes the cult-favorite Pick Six Vodka from an on-site well, and <strong><L to="yankee-distillers">Yankee Distillers</L></strong> in Clifton Park distills bourbon, rye, and vodka from 100% unmalted New York grain.</p>
      <h2 className="trail-h2">If you've got more time</h2>
      <ul className="trail-list">
        <li><strong>More breweries.</strong> <strong><L to="active-ingredient-brewing-company">Active Ingredient Brewing</L></strong> in Malta ("Science By The Pint," founded by two pharmacists), <strong><L to="common-roots-brewing">Common Roots</L></strong> in South Glens Falls, and <strong><L to="bound-by-fate-brewing">Bound by Fate</L></strong> in historic Schuylerville, where Burgoyne surrendered in 1777.</li>
        <li><strong>The Ballston Spa arm.</strong> The <strong><L to="ballston-spa-farmers-market">Ballston Spa Farmers' Market</L></strong> runs Thursdays (with free concerts) and Saturdays in Wiswall Park, and nearby <strong><L to="featherbed-lane-farm">Featherbed Lane Farm</L></strong> is the only farm in the county working draft horses, with a pick-your-own CSA and sleigh rides.</li>
        <li><strong>Fall traditions.</strong> <strong><L to="devoe-s-rainbow-orchards">DeVoe's Rainbow Orchards</L></strong> in Halfmoon for U-pick apples and cider, and <strong><L to="schuyler-farms">Schuyler Farms</L></strong> in Schuylerville for hayrides and a corn maze near the Saratoga battlefield.</li>
        <li><strong>A glass of wine.</strong> <strong><L to="galway-rock">Galway Rock</L></strong> in Ballston Lake pours estate wines from cold-hardy grapes with countryside views.</li>
      </ul>
      <h2 className="trail-h2">A few practical notes</h2>
      <p>The Spa City market is Sunday and runs year-round; the downtown Saratoga market runs midweek and Saturday — so build the morning around whichever you want. The big thing to plan around is racing season: from late July into early September the track is running, and Saratoga Springs gets packed and pricey, so either lean into the energy or aim for the shoulder seasons. Dancing Grain's sunflower festival is a summer highlight worth timing for. And with this many breweries and distilleries close together, bring a designated driver.</p>
      <p className="trail-crosslinks">The full Saratoga lineup is on the Almanac: <strong><Link to="/county/saratoga/craftbeverages">Saratoga County craft beverages</Link></strong> and <strong><Link to="/county/saratoga/markets">markets</Link></strong>.</p>
      <p className="trail-close">Mineral springs, grain fields, a city you can walk — one very good Saturday.</p>
    </>
  ),
  "a-saturday-in-the-battenkill-valley": () => (
    <>
      <p className="trail-lede">Up in the northeast corner of the region, hard against the Vermont line, Washington County is farm country in the deepest sense — covered-bridge dairy farms worked by the same families for six generations, a wild-trout river running through the middle of it, fiber mills spinning local wool, and New York's oldest pick-your-own orchard. The Battenkill Valley is quieter and more agricultural than almost anywhere else in these guides, and that's the whole appeal. Here's a loop through Greenwich, Salem, Cambridge, and Granville.</p>
      <h2 className="trail-h2">Morning — Greenwich</h2>
      <p>Start in Greenwich, the valley's hub. <strong><L to="hand-melon-farm">Hand Melon Farm</L></strong> on Route 29 is a historic 425-acre family farm famous for the Hand Melon — a cantaloupe three generations of presidents and celebrities have sought out — with U-pick berries in season and a market across from the fairgrounds. For fiber folks, <strong><L to="battenkill-fibers">Battenkill Fibers</L></strong> is a worsted spinning mill that processes wool for shepherds across the Northeast (farmers always get their own fiber back), and beekeepers will want to see <strong><L to="betterbee">Betterbee</L></strong>, a nationally known supply and education center. If it's Wednesday, the <strong><L to="greenwich-farmers-market-gather">Greenwich Farmers' Market</L></strong> runs year-round on Main Street.</p>
      <h2 className="trail-h2">Late morning — Salem dairy country</h2>
      <p>Head east to Salem, where the dairy runs deep. <strong><L to="battenkill-valley-creamery">Battenkill Valley Creamery</L></strong> is a fifth-generation farm that bottles its own milk on-site — award-winning whole milk, cream, and buttermilk in glass bottles, plus ultra-premium homemade ice cream, with a farm store open daily. (An ice cream here is non-negotiable.) Nearby, <strong><L to="sheldon-farms">Sheldon Farms</L></strong> has worked the banks of the Battenkill since 1845, known for legendary sweet corn and heirloom potatoes, and <strong><L to="gardenworks-farm">Gardenworks Farm</L></strong> is a fourth-generation destination with U-pick berries and flowers, a renovated dairy-barn marketplace, and a weekend farm café — a fine spot for lunch.</p>
      <h2 className="trail-h2">Midday — Cambridge and the river</h2>
      <p>Drift south to Cambridge, a handsome village with a strong arts streak and one of the largest rural markets around: the <strong><L to="cambridge-valley-farmers-market">Cambridge Valley Farmers' Market</L></strong> runs producer-only, year-round, on Sunday mornings. <strong><L to="bernard-farm">Bernard Farm</L></strong> keeps a roadside stand on Route 22 (Thursday–Sunday).</p>
      <p>Cambridge is also your gateway to the river itself. The <strong><L to="battenkill-river-corridor">Battenkill</L></strong> is widely regarded as one of the finest wild-trout streams in the eastern U.S. — clear, cold, and lined with public access points — and <strong><L to="battenkill-valley-outdoors">Battenkill Valley Outdoors</L></strong> has been renting canoes, kayaks, and tubes (with shuttles) since 2003. An hour on the water is the perfect midday break, and the quiet country roads here are made for cycling past the covered bridges.</p>
      <h2 className="trail-h2">Afternoon — Granville's orchard and cider</h2>
      <p>Drive north to Granville and <strong><L to="hicks-orchard-slyboro-ciderhouse">Hicks Orchard</L></strong> — New York's oldest pick-your-own, a family tradition since 1905, now in its 121st season, with 24-plus apple varieties, apple-wood-fired pizza, cider donuts, barnyard animals, and weekend live music. On the same property, <strong><L to="slyboro-ciderhouse">Slyboro Ciderhouse</L></strong> makes award-winning hard ciders, ice ciders, and apple brandy from estate heritage apples, with a tasting room doing cider-and-cheese pairings. It's the ideal way to close a farm day — orchard, pizza, and a glass of something serious, all in one stop.</p>
      <h2 className="trail-h2">If you've got more time</h2>
      <ul className="trail-list">
        <li><strong>The breweries.</strong> <strong><L to="scotlander-brewing-company">Scotlander Brewing</L></strong> is a hilltop farm nano-brewery in Argyle with its own hopyard and camping; <strong><L to="slate-town-brewing">Slate Town Brewing</L></strong> in Granville does pizza and wings; and <strong><L to="argyle-brewing">Argyle Brewing</L></strong> — the county's first farm brewery, famously "dry town, wet basements" — has taprooms in Greenwich and Cambridge.</li>
        <li><strong>More farms.</strong> <strong><L to="the-farm-store-at-tiashoke">The Farm Store at Tiashoke</L></strong> in Easton is a fourth-generation dairy with a store in a 200-year-old barn (beef, pork, cheese, cider donuts, 90-plus pumpkin varieties), and <strong><L to="dough-haven-farm">Dough Haven Farm</L></strong> is a veteran-owned agroforestry farm growing log-grown mushrooms.</li>
        <li><strong>Cheese and weaving.</strong> <strong><L to="argyle-cheese-farmer">Argyle Cheese Farmer</L></strong> makes award-winning farmstead yogurt and cheese with viewing windows into the make room, and <strong><L to="crazy-as-a-loom-weaving-studio">Crazy As A Loom</L></strong> in Kingsbury is a working weaving studio in a 1790 building.</li>
        <li><strong>Toward Lake George.</strong> Out at Fort Ann, <strong><L to="battle-hill-brewing">Battle Hill Brewing</L></strong> sits at a Revolutionary battle site, and <strong><L to="lake-george-distilling">Lake George Distilling</L></strong> makes whiskey on a farm five minutes from the lake — a natural bridge if you're continuing north.</li>
      </ul>
      <h2 className="trail-h2">A few practical notes</h2>
      <p>The markets vary by day — Greenwich is Wednesday, Cambridge is Sunday, <strong><L to="salem-farmers-market">Salem</L></strong> is Saturday — so build around whichever you want. Several farm stores (Sheldon, Gardenworks) are seasonal, roughly mid-May into October, and Hicks Orchard's pick-your-own is mostly a fall affair, so check before a long drive. The Battenkill paddling and fishing are warm-weather pursuits. And with breweries and a cidery on the route, bring a designated driver. This is genuinely rural country near the Vermont line, so cell service gets patchy — download directions first.</p>
      <p className="trail-crosslinks">The full Washington County lineup is on the Almanac: <strong><Link to="/county/washington/food">farms &amp; food</Link></strong> and <strong><Link to="/county/washington/craftbeverages">craft beverages</Link></strong>.</p>
      <p className="trail-close">A wild-trout river, covered-bridge dairy farms, the oldest orchard in the state — one very good Saturday.</p>
    </>
  ),
  "a-saturday-in-the-dutchess-river-towns": () => (
    <>
      <p className="trail-lede">The northern Dutchess river towns — Rhinebeck, Red Hook, Tivoli — are the Hudson Valley at its most postcard-perfect: historic village Main Streets, fourth-generation farm stands, orchards that have been worked since the 1700s, and a presidential corridor just to the south. It's an easy, genteel day, the kind you can do at a stroll. Here's a loop built around the river towns, with Hyde Park's mansions and a deep eastern distillery belt waiting if you want to keep going.</p>
      <p>One scheduling note up front: the area's flagship market runs *Sundays*, so if you can swing a Sunday, do — but the farm stands here are open daily, so any day works.</p>
      <h2 className="trail-h2">Morning — Rhinebeck</h2>
      <p>Start in the village of Rhinebeck. If it's a Sunday, the <strong><L to="rhinebeck-farmers-market">Rhinebeck Farmers' Market</L></strong> is the place to be — founded in 1994, 30-plus vendors, live music, and named Best Farmers' Market in the Hudson Valley five years running. Any other day, point the car to the <strong><L to="migliorelli-farm-stand">Migliorelli Farm Stand</L></strong> on River Road, a fourth-generation operation rooted in 1933 — they grow 130-plus varieties on Hudson River farmland permanently protected by a Scenic Hudson easement. Either way, you'll leave with the cooler full.</p>
      <p>While you're in the village, <strong><L to="merriweather-s">Merriweather's</L></strong> makes hand-cut natural soaps if you want a small keepsake, and the nurseries here are destinations in their own right — the <strong><L to="phantom-gardener">Phantom Gardener</L></strong> is a six-acre organic garden center, and <strong><L to="northern-dutchess-botanical-gardens">Northern Dutchess Botanical Gardens</L></strong> has grown its own stock on-site for 46 years.</p>
      <h2 className="trail-h2">Late morning — the Red Hook farm stands</h2>
      <p>Head north to Red Hook, where two of the most accessible farm stands in Dutchess sit minutes apart. <strong><L to="greig-farm-2">Greig Farm</L></strong> is open daily for pick-your-own, a farm store, and family activities; <strong><L to="northaven-pastures">Northaven Pastures</L></strong> sells locally raised pastured meats every day of the week. Between them you've got dinner sorted.</p>
      <h2 className="trail-h2">Midday — cider at an 1798 orchard</h2>
      <p>For lunch and a pour, <strong><L to="rose-hill-ferments">Rose Hill Ferments</L></strong> in Red Hook makes low-intervention cider and wine on the grounds of Rose Hill Farm — a historic orchard founded in 1798, now growing 50-plus cider-specific apple varieties. The ciders are made from estate fruit with native yeast, nothing added or removed, and the taproom (Friday–Sunday) has orchard seating; immersive cidery tours run by reservation. It's the loveliest midday stop on the loop.</p>
      <h2 className="trail-h2">Afternoon — Tivoli and the river</h2>
      <p>Drift up to Tivoli, the smallest and most bohemian of the river villages — a walkable handful of blocks worth a wander, with <strong><L to="northwind-farms">Northwind Farms</L></strong> raising pastured livestock just outside town. From here the Hudson is right there; it's a fine place to let the afternoon go slack before deciding how far you want to push the day.</p>
      <h2 className="trail-h2">The Hyde Park arm — history and a sake brewery</h2>
      <p>Point south on Route 9 and you're in presidential country: the <strong>FDR Home and Presidential Library</strong>, the <strong>Vanderbilt Mansion</strong>, and the <strong>Culinary Institute of America</strong>, where a reservation buys you one of the better meals in the valley. The drinks here are a study in contrasts — <strong><L to="dassai-blue-sake-brewery">Dassai Blue Sake Brewery</L></strong> is an $80-million, Pelli-designed sake brewery from a prestigious Japanese maker, opened in 2023 a mile from the CIA, while <strong><L to="hyde-park-brewing-company">Hyde Park Brewing</L></strong> is a beloved old brewpub directly across from the FDR site. Tour one, eat at the other.</p>
      <h2 className="trail-h2">If you've got more time — the eastern distillery belt</h2>
      <p>East of the river towns, the farmland fills with wineries and distilleries:</p>
      <ul className="trail-list">
        <li><strong><L to="clinton-vineyards">Clinton Vineyards</L> — Clinton Corners.</strong> Family-owned since 1977; the Seyval Blanc here is the wine that put the Hudson Valley back on the map after Prohibition.</li>
        <li><strong><L to="millbrook-vineyards-winery">Millbrook Vineyards &amp; Winery</L> — Millbrook.</strong> Dubbed "the Hudson Valley's flagship winery" by the *Times*, on a 130-acre estate.</li>
        <li><strong><L to="dutchs-spirits">Dutch's Spirits</L> — Pine Plains.</strong> A distillery on the site of the largest Prohibition-era still in the Northeast — Dutch Schultz's operation — with brick-oven pizza and tours of the original 1930s still ruins.</li>
        <li><strong><L to="taconic-distillery">Taconic Distillery</L> — Stanfordville,</strong> for spring-water bourbons, and <strong><L to="shady-knoll-orchards-distillery">Shady Knoll</L> — Millbrook,</strong> for orchard apple brandy.</li>
      </ul>
      <p>And for the grain-and-cheese inclined: <strong><L to="wild-hive-farm">Wild Hive Farm</L></strong> in Clinton Corners is the stone mill that revived Hudson Valley grain milling, and <strong><L to="chaseholm-farm-creamery-2">Chaseholm Farm Creamery</L></strong> in Pine Plains makes French-tradition cheeses from its own organic herd.</p>
      <h2 className="trail-h2">A few practical notes</h2>
      <p>The Rhinebeck market is Sunday; the farm stands (Migliorelli, Greig, Northaven) are daily; Rose Hill's taproom is Friday–Sunday — so build the day around whichever of those you most want. The Hyde Park presidential sites are ticketed and have set hours, and CIA meals book up, so reserve ahead. And if you're hitting the eastern distillery belt, bring a designated driver. Two enormous events take over Rhinebeck seasonally — the <strong><L to="dutchess-county-fair-2">Dutchess County Fair</L></strong> in August and the <strong><L to="nys-sheep-and-wool-festival">NYS Sheep &amp; Wool Festival</L></strong> in October — so check the calendar before you go (and book lodging early if you're aiming for either).</p>
      <p className="trail-crosslinks">The full lineup is on the Almanac: <strong><Link to="/county/dutchess/markets">Dutchess County markets</Link></strong> and <strong><Link to="/county/dutchess/craftbeverages">craft beverages</Link></strong>.</p>
      <p className="trail-close">River villages, old orchards, one very good Saturday.</p>
    </>
  ),
  "a-saturday-in-the-harlem-valley": () => (
    <>
      <p className="trail-lede">Along the eastern edge of Dutchess County, hard against the Connecticut line, the Harlem Valley runs north to south through some of the prettiest farm country in the region — a chain of railroad villages strung along an old rail line that's now a trail, with a thousand-acre organic farm, a maple estate, and Main Streets full of bookshops and antiques. It's a quieter, slower day than the river towns to the west, and it has one thing the others don't: you can do a good chunk of it on foot or by bike. Here's a loop anchored on Millerton, Amenia, and Wassaic.</p>
      <p>A nice wrinkle — Metro-North's Harlem Line ends right in Wassaic, so this is one of the few guides you can do car-free if you want to.</p>
      <h2 className="trail-h2">Morning — Millerton</h2>
      <p>Start in Millerton, a walkable Main Street village that's become a destination in its own right — antiques, bookstores, and the flagship of a well-known tea company among them. The <strong><L to="millerton-farmers-market">Millerton Farmers' Market</L></strong> runs Saturdays year-round at the Methodist Church (outdoors May–October, indoors twice monthly in winter), with sustainably grown produce, pasture-raised meats, and cheeses, plus Double Up Food Bucks for SNAP shoppers.</p>
      <p>Just south on Route 22, <strong><L to="mcenroe-organic-farm">McEnroe Organic Farm</L></strong> is the area's flagship — a NOFA-certified organic farm working over 1,000 acres since 1987, with an on-site market, an eatery, and farm tours. It's a fine place for breakfast and to stock the cooler.</p>
      <h2 className="trail-h2">Late morning — the rail trail</h2>
      <p>The spine of the day is the <strong>Harlem Valley Rail Trail</strong>, a flat, paved former rail line that runs through Millerton, Amenia, and Wassaic with valley and ridge views the whole way. Walk or bike as much as you like — it's free, easy, and dog- and family-friendly, and it connects the villages you'll be visiting anyway.</p>
      <h2 className="trail-h2">Midday — Amenia and Wassaic</h2>
      <p>Drift south to Amenia and Wassaic, two small hamlets with outsized character. In Wassaic, <strong><L to="battle-hill-forge">Battle Hill Forge</L></strong> has been making heirloom hand-forged garden and landscape ironwork since 2004 — work that's been shown at the Met Cloisters and the Norman Rockwell Museum. Wassaic is also home to a well-regarded contemporary art space housed in a historic grain elevator, worth a look if a show is up. Amenia's <strong><L to="amenia-farmers-market">farmers' market</L></strong> runs Friday evenings May through December if your timing lines up, and the town's historic estate inn is a destination restaurant in its own right.</p>
      <h2 className="trail-h2">Afternoon — a maple estate</h2>
      <p>A few minutes south in Dover Plains, <strong><L to="crown-maple-at-madava-farms">Crown Maple at Madava Farms</L></strong> produces estate organic maple syrup on an 800-acre farm, with tours and tastings in a beautifully built sugarhouse — one of the most polished maple experiences in the state. Nearby <strong><L to="soukup-farms">Soukup Farms</L></strong> is a third-generation operation with over 2,000 taps and a year-round farm store (maple, plus hot sauce, mustard, and candles).</p>
      <h2 className="trail-h2">Late afternoon — a bourbon to finish</h2>
      <p>Swing west toward Stanfordville and <strong><L to="taconic-distillery">Taconic Distillery</L></strong> on Rolling Hills Farm, where spring water from the property goes into well-regarded bourbons and ryes — Founders Rye, the Dutchess Private Reserve Bourbon. The rustic tasting room pours flights, and if you check in on the county's craft-beverage trail, you'll leave with a free Glencairn glass.</p>
      <h2 className="trail-h2">If you've got more time</h2>
      <ul className="trail-list">
        <li><strong>More Millerton farms.</strong> <strong><L to="rock-steady-farm">Rock Steady Farm</L></strong> is an LGBTQ+ worker-owned certified-organic farm with a Saturday-morning farm stand, and <strong><L to="dirty-girl-farm-2">Dirty Girl Farm</L></strong> is a micro-creamery making fresh goat cheese, yogurt, and bottled goat milk.</li>
        <li><strong>The southern villages.</strong> Pawling is a charming railroad village near the Appalachian Trail with its own <strong><L to="pawling-farmers-market">Saturday market</L></strong> on the green; in Pleasant Valley, <strong><L to="cronin-s-maple-farm">Cronin's Maple Farm</L></strong> and <strong><L to="quattro-s-poultry-game-farm">Quattro's Poultry &amp; Game Farm</L></strong> are worth a stop.</li>
        <li><strong>Stanfordville.</strong> <strong><L to="big-rock-community-farms">Big Rock Community Farms</L></strong> keeps a year-round farm market near the distillery, so you can combine the two.</li>
      </ul>
      <h2 className="trail-h2">A few practical notes</h2>
      <p>The Millerton market runs Saturdays year-round; Amenia's is Friday evenings; build the day around whichever you want. The rail trail is the easy throughline — flat, free, and the reason this corner is so pleasant on foot or two wheels. Crown Maple's tours are seasonal, so check before you count on one. And the distillery means a designated driver, as always. If you're coming up from the city without a car, the Wassaic train station puts you right on the trail.</p>
      <p className="trail-crosslinks">The full eastern-Dutchess lineup is on the Almanac: <strong><Link to="/county/dutchess/markets">Dutchess County markets</Link></strong> and <strong><Link to="/county/dutchess/maple">maple producers</Link></strong>.</p>
      <p className="trail-close">Railroad villages, a trail between them, one very good Saturday.</p>
    </>
  ),
  "a-saturday-in-the-helderbergs": () => (
    <>
      <p className="trail-lede">Just west of Albany, the land rises into the Helderbergs — a limestone escarpment with some of the best long views in the Capital Region, a century farm at its foot, a village full of makers, and hilltown back roads dotted with maple sugarhouses and fiber farms. It's the closest of these day trips to the city, which makes it the easiest to do on a whim, and it packs a remarkable amount into a small radius. Here's a loop built around the escarpment, Altamont, and the hilltowns, with a Warehouse District finish back in Albany.</p>
      <h2 className="trail-h2">Morning — the escarpment and the century farm</h2>
      <p>Start on top, at John Boyd Thacher State Park, where the Indian Ladder Trail threads along the base of the limestone cliffs with sweeping views over the Hudson-Mohawk valley — one of the great short walks in the region. Then drop down to its namesake, <strong><L to="indian-ladder-farms">Indian Ladder Farms</L></strong> in Altamont, a fourth-generation family farm established in 1916 at the foot of the escarpment. Over 300 acres of orchard, a year-round farm market and bakery known for its cider doughnuts, pick-your-own in season, and the Yellow Rock Café for breakfast and brunch. It's the anchor of the whole day — and a great place to start it.</p>
      <h2 className="trail-h2">Late morning — Altamont's makers</h2>
      <p>The village of Altamont is small and worth a wander. <strong><L to="helderberg-blacksmith">Helderberg Blacksmith</L></strong> forges everything from colonial-style reproductions to clean contemporary ironwork, and <strong><L to="stephanie-morton-hand-weaver">Stephanie Morton</L></strong> is a traditionally trained weaver and natural dyer working with locally grown wool, cotton, and alpaca and dyestuffs like madder and indigo — she teaches workshops, too. For gardeners, <strong><L to="helderledge-farm">Helderledge Farm</L></strong> is a local nursery worth a look.</p>
      <h2 className="trail-h2">Midday — cider, beer, and pizza on the farm</h2>
      <p>Head back to Indian Ladder, where the <strong><L to="indian-ladder-farms-cidery-and-brewery">Cidery &amp; Brewery</L></strong> makes true farm-to-glass cider and beer from apples, hops, and barley grown on the farm and other New York land, with a taproom and biergarten overlooking the hop yard. On summer weekends, the <strong><L to="indian-ladder-farms-pizza-garden">Pizza Garden</L></strong> — a seasonal outpost of Troy's DeFazio's — fires wood-oven pizza out in the biergarten. Lunch, sorted.</p>
      <h2 className="trail-h2">Afternoon — into the hilltowns</h2>
      <p>Climb up into the Hilltowns — Berne, Knox, East Berne — where the farms get smaller and the roads quieter. <strong><L to="helder-herdwyck-farm">Helder~Herdwyck Farm</L></strong> in East Berne raises rare Herdwick sheep — the breed Beatrix Potter championed, and only the second flock in the country — selling wool, roving, and pastured meats from the farm store. Nearby <strong><L to="helderberg-alpacas">Helderberg Alpacas</L></strong> welcomes farm visits by appointment and sells fiber and yarn from its own animals.</p>
      <p>This is maple and honey country, too. <strong><L to="partridge-run-farm-and-apiary">Partridge Run Farm &amp; Apiary</L></strong> in Berne is open daily for raw wildflower honey and beeswax goods, and <strong><L to="helderberg-1839-maple-vine">Helderberg 1839</L></strong> in Knox makes pure maple syrup and even a maple wine from its own syrup (call ahead). If you want to stretch your legs again, <strong><L to="partridge-run-wildlife-management-area">Partridge Run Wildlife Management Area</L></strong> has 40-plus miles of trails and a few waterfalls across 4,500 acres of high terrain.</p>
      <h2 className="trail-h2">Late afternoon — a Warehouse District finish</h2>
      <p>Drop back toward Albany and end in the city's Warehouse District, home to two New York firsts. <strong><L to="nine-pin-cider">Nine Pin Cider</L></strong> is the state's first farm cidery, pouring 18 taps of cider made from Capital Region and Hudson Valley apples alongside sourdough pizza and house charcuterie. A few doors away, <strong><L to="albany-distilling-company">Albany Distilling Company</L></strong> is the first distillery in Albany since Prohibition, making Ironweed whiskey and Quackenbush rum. If you'd rather a historic brewpub, <strong><L to="ch-evans-brewing-albany-pump-station">C.H. Evans Brewing at the Albany Pump Station</L></strong> occupies a former pumping station at the foot of the Hudson waterfront.</p>
      <h2 className="trail-h2">If you've got more time</h2>
      <ul className="trail-list">
        <li><strong>The southern Helderbergs.</strong> <strong><L to="stanton-s-feura-farm-markets">Stanton's Feura Farm &amp; Markets</L></strong> in Feura Bush is a longtime family farm market (Mon–Sat), and <strong><L to="heather-ridge-farm-bees-knees-cafe">Heather Ridge Farm &amp; Bees Knees Café</L></strong> in Preston Hollow serves a Saturday farm lunch alongside grass-fed meats and woolen goods.</li>
        <li><strong>A pine-barrens walk.</strong> The <strong><L to="albany-pine-bush-preserve">Albany Pine Bush Preserve</L></strong> protects one of the best inland pine barrens on earth — home to the rare Karner blue butterfly — with 20-plus miles of trails and a free Discovery Center.</li>
        <li><strong>Provisions.</strong> <strong><L to="honest-weight-food-co-op">Honest Weight Food Co-op</L></strong>, member-owned since 1976, has the Capital District's deepest selection of local and organic groceries.</li>
        <li><strong>In August,</strong> the <strong><L to="altamont-fair-2">Altamont Fair</L></strong> is one of the region's oldest, with livestock shows, 4-H, and rides at the foot of the hills.</li>
      </ul>
      <h2 className="trail-h2">A few practical notes</h2>
      <p>The Indian Ladder Pizza Garden is a summer, Friday-through-Sunday thing, and the cidery taproom runs Thursday through Sunday, so weekend afternoons are the sweet spot. Several hilltown farms (Helderberg Alpacas, Helderberg 1839) are call-ahead or by-appointment, so phone before you drive up. Thacher Park's escarpment trail is the scenic highlight — best in clear weather for the views — and the Warehouse District cideries and distillery mean a designated driver, as always. The Helderberg-Hudson Rail Trail, which runs from Voorheesville toward the city, is a flat, easy bonus if you've got bikes.</p>
      <p className="trail-crosslinks">The full lineup is on the Almanac: <strong><Link to="/county/albany/craftbeverages">Albany County craft beverages</Link></strong> and <strong><Link to="/county/albany/food">farms &amp; food</Link></strong>.</p>
      <p className="trail-close">An escarpment, a century farm, the hilltowns behind it — one very good Saturday, right in the Capital Region's backyard.</p>
    </>
  ),
  "a-saturday-in-the-hudson-highlands": () => (
    <>
      <p className="trail-lede">Putnam County is one of the smallest in these guides, but it punches well above its size, because this is where the Hudson River squeezes between the mountains and the scenery turns spectacular. Cold Spring is one of the most charming river villages anywhere, the farmers market may be the prettiest in the valley, and a cluster of farms — some worked since before the Revolution — fills in the rest. It's a scenic river-village-and-farm day more than a sprawling farm loop, and it's an easy one to do without a car. Here's a Saturday in the Highlands.</p>
      <h2 className="trail-h2">Morning — Cold Spring &amp; Garrison</h2>
      <p>Start at the <strong><L to="cold-spring-farmers-market-at-boscobel-2">Cold Spring Farmers Market at Boscobel</L></strong> — held year-round on Saturdays on the grounds of the historic Boscobel House and Gardens in Garrison, with the Hudson Highlands rising across the river. It's genuinely one of the most scenic markets in the region, with produce, meat, dairy, and baked goods from local farms. Among the vendors, look for <strong><L to="hudson-highlands-garlic">Hudson Highlands Garlic</L></strong>, a small grower of heirloom and specialty garlic.</p>
      <p>Just up the road, <strong><L to="glynwood-farm-store">Glynwood Farm Store</L></strong> is a USDA-certified-organic, animal-welfare-certified farm store at the Glynwood estate, selling seasonal produce, pasture-raised meats, and eggs — the retail face of a major regional farming institution. For garden plants and a roadside farm stand that's been a fixture since 1982, <strong><L to="vera-s-marketplace">Vera's Marketplace</L></strong> is right on Route 9, and <strong><L to="cold-spring-apothecary">Cold Spring Apothecary</L></strong> makes small-batch botanical skincare.</p>
      <h2 className="trail-h2">Midday — the village and the river</h2>
      <p>Cold Spring's compact Main Street runs straight down to the Hudson, lined with antiques shops, cafés, and river views toward Storm King and West Point. It's the natural place for lunch, and if you're up for it, the trailheads for Breakneck Ridge and Bull Hill are right here — some of the most popular (and steep) hikes in the valley. Boscobel itself, a beautifully restored Federal-era mansion with formal gardens above the river, is worth the visit even if it's not a market day.</p>
      <h2 className="trail-h2">Afternoon — the Brewster farm belt</h2>
      <p>Head east across the county to Brewster, where Putnam's farm country is. <strong><L to="tilly-foster-farm-educational-institute">Tilly Foster Farm</L></strong> is the county's flagship agricultural center — 258 acres of organic gardens, hiking trails, and working farm animals (alpacas, pigs, horses), with hands-on programs and seasonal events, and one of the most accessible farm-education spots in the lower valley. Nearby, <strong><L to="ryder-farm">Ryder Farm</L></strong> has been in the same family since 1795 — certified organic vegetables, herbs, and flowers, with a CSA and on-farm sales at the <strong><L to="ryder-farm-cottage">Ryder Farm Cottage</L></strong>. In the fall, <strong><L to="salinger-s-orchard-2">Salinger's Orchard</L></strong> sells apples, cider, and pumpkins from its farm stand on Guinea Road.</p>
      <h2 className="trail-h2">Late afternoon</h2>
      <p>If it's Sunday rather than Saturday, the year-round <strong><L to="hudson-valley-regional-farmers-market-brewster">Hudson Valley Regional Farmers Market</L></strong> in Brewster runs 10 to 2. And <strong><L to="green-chimneys">Green Chimneys</L></strong> in Brewster — a remarkable nonprofit pairing a therapeutic school with a working farm and a licensed wildlife-rehabilitation center — holds public education events and programs worth catching when they're on.</p>
      <h2 className="trail-h2">If you've got more time</h2>
      <ul className="trail-list">
        <li><strong>More farms.</strong> <strong><L to="longhaul-farm">Longhaul Farm</L></strong> grows vegetables on South Mountain Pass in Garrison, and <strong><L to="brimstone-hollow-farm">Brimstone Hollow Farm</L></strong> in Brewster sells raw honey and farm eggs.</li>
        <li><strong>For aspiring farmers.</strong> The <strong><L to="glynwood-center-for-regional-food-and-farming-2">Glynwood Center for Regional Food and Farming</L></strong> in Cold Spring runs one of the region's best beginning-farmer training programs.</li>
        <li><strong>Central county.</strong> The <strong><L to="carmel-farmers-market">Carmel Farmers Market</L></strong> serves the middle of the county, and <strong><L to="the-feed-barn">The Feed Barn</L></strong> in Mahopac stocks feed and supplies for homesteaders.</li>
      </ul>
      <h2 className="trail-h2">A few practical notes</h2>
      <p>The Boscobel market is the rare year-round, every-Saturday anchor, which makes Cold Spring the easiest base for the day. Here's the best part: Cold Spring sits right on Metro-North's Hudson Line, and the village is entirely walkable from the station — you can do the market, Main Street, the riverfront, and a hike without ever getting in a car. The Brewster farms are the other half of the county and add a good 30–40 minutes of driving, so on a tight day, pick the Highlands or the farm belt and save the other. Salinger's and the orchards are seasonal, peaking in fall.</p>
      <p className="trail-crosslinks">The full Putnam lineup is on the Almanac: <strong><Link to="/county/putnam/food">farms &amp; food</Link></strong> and <strong><Link to="/county/putnam/markets">markets</Link></strong>.</p>
      <p className="trail-close">A river between the mountains, a market with a view, a farm older than the country — one very good Saturday.</p>
    </>
  ),
  "a-saturday-in-the-schoharie-valley": () => (
    <>
      <p className="trail-lede">They called it the Breadbasket of the American Revolution, and the Schoharie Valley still earns the name — a wide, fertile river valley of six-generation farms, sweet corn and potatoes, a revitalized resort village, and farm-to-bottle spirits made from crops grown in the same fields. Tucked between the Catskills and the Mohawk Valley, it doesn't get the weekend crowds of the river towns, and it rewards anyone who makes the drive. Here's a loop up the valley from Middleburgh through Schoharie to Cobleskill, with Sharon Springs and a Catskill-foothill cider cluster as arms.</p>
      <h2 className="trail-h2">Morning — Middleburgh</h2>
      <p>Start in Middleburgh, the agricultural heart of the valley. <strong><L to="barber-s-farm">Barber's Farm</L></strong> is a six-generation family farm established in 1857, with one of the most celebrated farm stands in the Capital Region — 60-plus hand-harvested varieties, open daily May through November, plus seven greenhouses of starts and baskets. Right on the same farm, <strong><L to="1857-spirits-barbers-farm-distillery">1857 Spirits</L></strong> makes estate potato vodka from potatoes grown in the family fields — true farm-to-bottle, with a tasting room at the farm stand. For pick-your-own, <strong><L to="bohringer-s-fruit-farm">Bohringer's Fruit Farm</L></strong> is a Schoharie Valley institution (strawberries through apples, June to November).</p>
      <p>Work some of it off on the <strong><L to="schoharie-valley-rail-trail">Schoharie Valley Rail Trail</L></strong>, a flat path with views of the Helderberg Escarpment and Vroman's Nose — the dramatic flatiron cliff that hangs over the valley and rewards a short, steep climb with one of the best views in the region.</p>
      <h2 className="trail-h2">Midday — Schoharie village</h2>
      <p>Head down the valley to Schoharie village, with its deep Revolutionary history — the 1772 Old Stone Fort is now a museum worth a look. <strong><L to="terrace-mountain-orchard">Terrace Mountain Orchard</L></strong> does U-pick apples on the hillside in fall, and <strong><L to="cotton-hill-creamery-2">Cotton Hill Creamery</L></strong> makes fresh goat cheese from pastured Alpine goats. It's an easy place to find lunch among the historic Main Street.</p>
      <h2 className="trail-h2">Afternoon — Cobleskill and maple</h2>
      <p>Continue to Cobleskill, the valley's hub and home to SUNY Cobleskill's working agricultural college. <strong><L to="maple-hill-syrup-farms">Maple Hill Syrup Farms</L></strong> is a six-generation operation with a country store and year-round tours, wood-fired evaporation, and spring and fall festivals. On Sundays through October, the new <strong><L to="schoharie-county-farmers-market">Schoharie County Farmers Market</L></strong> runs at the Sunshine Fairgrounds. And the famous show caverns just outside town are an easy family detour if you've never been underground.</p>
      <h2 className="trail-h2">Late afternoon — Sharon Springs</h2>
      <p>Finish in Sharon Springs, a historic spa village that's been beautifully revitalized in the last decade. The anchor is the <strong><L to="beekman-1802-mercantile">Beekman 1802 Mercantile</L></strong> — the flagship "Kindness Shop" of the goat-milk skincare brand founded at the nearby Beekman Farm, widely credited with bringing the village back to life — full of soaps, provisions, and home goods. Just outside town, <strong><L to="bison-island-ranch">Bison Island Ranch</L></strong> raises grass-fed bison with a Saturday-morning ranch store (and tipi stays on a stocked pond), and <strong><L to="elderberry-herb-farm">Elderberry Herb Farm</L></strong> grows organic herbs on a property that was a thriving hops farm in the 1800s. The <strong><L to="sharon-springs-farmers-market">Sharon Springs Farmers Market</L></strong> rounds it out.</p>
      <h2 className="trail-h2">If you've got more time — the Catskill-foothill farms</h2>
      <p>South and west of the valley floor, the land climbs into the Catskill foothills, where a remarkable cluster of small farms and cideries sits along the back roads:</p>
      <ul className="trail-list">
        <li><strong><L to="sap-bush-hollow-farm">Sap Bush Hollow Farm</L></strong> — West Fulton. A three-generation grass-fed farm since 1979, with a Saturday farm-to-table café and espresso bar, an honor-system store open 24/7, and its own wool.</li>
        <li><strong><L to="scrumpy-ewe-cider">Scrumpy Ewe Cider</L></strong> — West Fulton. Minimal-intervention cider from individually picked apples, with the namesake sheep grazing the orchard; tasting room open weekends, May through December.</li>
        <li><strong><L to="kymar-farm-winery-distillery">KyMar Farm Winery &amp; Distillery</L></strong> — Charlotteville. The first distillery in the county since Prohibition, known for its Cinister cinnamon moonshine and estate wines.</li>
        <li><strong><L to="sunken-city-cider">Sunken City Cider</L></strong> — Gilboa. A creekside cidery, orchard, and live-music venue named for the village of Old Gilboa, submerged under the Schoharie Reservoir in 1926.</li>
        <li><strong><L to="buck-hill-farm">Buck Hill Farm</L></strong> — Jefferson. Organic maple with a year-round Sunday pancake breakfast, farm animals, and a gift shop.</li>
      </ul>
      <p>And for a quiet walk, the <strong><L to="george-landis-arboretum">George Landis Arboretum</L></strong> in Esperance is open every day of the year, with old-growth forest and trails.</p>
      <h2 className="trail-h2">A few practical notes</h2>
      <p>Barber's farm stand is daily in season; pick-your-own at Bohringer's and Terrace Mountain runs roughly June through November and peaks in fall. The Beekman Mercantile is open Wednesday through Monday, and Sharon Springs is at its best on a weekend afternoon when the village is humming. The foothill cideries (Scrumpy Ewe, Sunken City) keep weekend hours, and the distilleries mean a designated driver. This is a big rural county — the valley towns and the foothill farms are really two arms of the same trip, so on a single day, pick one and save the other for next time.</p>
      <p className="trail-crosslinks">The full Schoharie lineup is on the Almanac: <strong><Link to="/county/schoharie/food">farms &amp; food</Link></strong> and <strong><Link to="/county/schoharie/craftbeverages">craft beverages</Link></strong>.</p>
      <p className="trail-close">A revolutionary breadbasket, potato vodka, a village brought back to life — one very good Saturday.</p>
    </>
  ),
  "a-saturday-in-the-shawangunks": () => (
    <>
      <p className="trail-lede">Some corners of the Hudson Valley wear their cliffs on the horizon. Down at the foot of the Shawangunk Ridge — the white-quartzite escarpment that draws climbers and hikers from all over — New Paltz and its neighbors sit in a valley thick with orchards, rail-trail miles, and the distillery that started New York's whole craft-spirits movement. This is a Saturday for people who want a walk in the morning and good things in a glass by afternoon, built around New Paltz, Gardiner, and the Rondout Valley to the west.</p>
      <h2 className="trail-h2">Morning — the ridge and the rail trail</h2>
      <p>Start in New Paltz with the Gunks in front of you. The Wallkill Valley Rail Trail runs right through town — flat, shaded, and scenic, ideal for a morning walk or bike with the ridge in view (the Shawangunk preserves themselves, Minnewaska and Mohonk, are a short drive up the mountain if you want a real hike, but their lots fill early on weekends, so go first if you go).</p>
      <p>When you're ready to pick rather than walk, <strong><L to="dressel-farms">Dressel Farms</L></strong> on Route 208 does pick-your-own apples and sells vegetables and seasonal produce right in the shadow of the ridge.</p>
      <h2 className="trail-h2">Late morning — the cradle of New York whiskey</h2>
      <p>A few minutes south in Gardiner sits a genuine landmark: <strong><L to="tuthilltown-spirits-distillery">Tuthilltown Spirits</L></strong>, founded in 2003 as the first legal whiskey distillery to open in New York since Prohibition. Its founder's advocacy is the reason the 2007 Farm Distillery Act exists — which is to say, half the cideries and distilleries in these guides owe this 36-acre spot at the foot of the Gunks their existence. It makes the Hudson Whiskey line — Baby Bourbon, Manhattan Rye, Single Malt — from local grain, beside an NRHP-listed 1788 gristmill. Take the tour and tasting; it's the historical heart of the whole region's drinks scene.</p>
      <h2 className="trail-h2">Midday — a farm-kitchen lunch in Accord</h2>
      <p>Head west into the Rondout Valley for lunch where the cider is made. <strong><L to="westwind-orchard">Westwind Orchard</L></strong> in Accord is a certified-organic orchard and cidery with an Italian-influenced farm kitchen turning out Neapolitan wood-fired pizza and fresh pasta on weekends, alongside its award-winning estate ciders. If you'd rather a brewery, <strong><L to="arrowood-farms">Arrowood Farms</L></strong> is just down the road — a terroir-driven farm brewery growing its own hops and rye, with the farm-to-table Apiary + Bar, fire pits, and Adirondack chairs out on the grass.</p>
      <h2 className="trail-h2">Afternoon — makers and provisions</h2>
      <p>The Rondout hamlets are full of old craft. In High Falls, the <strong><L to="canal-forge-blacksmith-shop">Canal Forge Blacksmith Shop</L></strong> is a working forge overlooking the Rondout Creek beside the old D&amp;H Canal, making fireplace tools, hardware, and ironwork (and teaching hands-on classes). While you're in High Falls, the <strong><L to="high-falls-food-co-op">High Falls Food Co-op</L></strong> — member-owned since 1974 — is a great spot to grab local provisions and something from the deli. And back toward Accord, <strong><L to="hudson-valley-seed-co">Hudson Valley Seed Co.</L></strong> keeps a walk-in shop and trial gardens, famous for its artist-designed seed packets that double as keepsakes.</p>
      <h2 className="trail-h2">Late afternoon — a tasting with a view</h2>
      <p>Finish on the Shawangunk Wine Trail, where the tasting rooms come with the ridge as a backdrop. <strong><L to="whitecliff-vineyard-winery">Whitecliff Vineyard</L></strong> in Gardiner has more than 30 years in the ground and a Riesling that once beat 1,300 wines from 27 countries for Best of Show — sweeping Shawangunk views from the tasting room. Or stay at Arrowood and let the afternoon run long by the fire pits.</p>
      <h2 className="trail-h2">If you've got more time</h2>
      <ul className="trail-list">
        <li><strong>The river arm (Highland).</strong> A mile from the <strong>Walkway Over the Hudson</strong> — the longest elevated pedestrian bridge in the world — <strong><L to="hudson-ale-works">Hudson Ale Works</L></strong> pours ten-plus house beers with a famous Bavarian pretzel, and <strong><L to="bad-seed-hard-cider">Bad Seed Hard Cider</L></strong> runs a weekend taproom and beer garden — the first American producer to can a genuinely dry cider.</li>
        <li><strong>The river wineries (Marlboro).</strong> <strong><L to="benmarl-winery">Benmarl</L></strong> holds New York Farm Winery License #1 and claims America's oldest vineyard, with Hudson River views; nearby <strong><L to="stoutridge-vineyard-distillery">Stoutridge</L></strong> makes "untouched" gravity-flow natural wines on a limestone ridge.</li>
        <li><strong>More New Paltz cider.</strong> <strong><L to="brooklyn-cider-house">Brooklyn Cider House at Twin Star Orchards</L></strong> pours Basque-style natural cider with seasonal *txotx* events; <strong><L to="kettleborough-cider-house">Kettleborough</L></strong> does dry traditional cider near the rail trail.</li>
        <li><strong>For foragers.</strong> Accord and Kerhonkson are home base to two of the region's best wild-food teachers — herbalist <strong><L to="dina-falconi-foraging-feasting">Dina Falconi</L></strong> and <strong><L to="catskill-fungi">Catskill Fungi</L></strong> — if a guided walk is more your speed than a tasting.</li>
      </ul>
      <h2 className="trail-h2">A few practical notes</h2>
      <p>If you want a real hike in the Gunks, get to the preserve lots early — weekends fill by mid-morning. Westwind's pizza kitchen is a weekend thing, so time lunch accordingly. The wine and spirits stops mean a designated driver, as always. And the rail trail is flat, free, and dog- and family-friendly if anyone in the car isn't up for a climb.</p>
      <p className="trail-crosslinks">The full southern-Ulster lineup is on the Almanac: <strong><Link to="/county/ulster/craftbeverages">Ulster County craft beverages</Link></strong>.</p>
      <p className="trail-close">Cliffs on the horizon, cider at the orchard, one very good Saturday.</p>
    </>
  ),
  "a-saturday-in-the-sullivan-catskills": () => (
    <>
      <p className="trail-lede">The western frontier of the Catskills is trout country — the Beaverkill and the Willowemoc, the streams where American dry fly fishing was born, winding past hamlets that have quietly become some of the most food- and arts-forward small towns in the region. Add the Delaware River, a deep bench of breweries and distilleries built into old firehouses, and one of the most striking cideries in the country, and Sullivan County makes for a rich, scenic day. Here's a loop along the Livingston Manor–Roscoe–Callicoon corridor, with the Delaware River and the Woodstock site waiting at the edges.</p>
      <h2 className="trail-h2">Morning — Livingston Manor and the birthplace of fly fishing</h2>
      <p>Start in Livingston Manor, a creekside hamlet that's become a genuine destination for food and the outdoors. On the banks of the Willowemoc, the <strong><L to="catskill-fly-fishing-center-museum-2">Catskill Fly Fishing Center &amp; Museum</L></strong> is the world's largest center devoted to the sport — the Fly Fishing Hall of Fame, a bamboo rod-making workshop, casting fields, and two miles of trails on 53 acres. Even if you've never held a rod, it's a lovely, only-here kind of stop. Just up the road, the <strong><L to="dec-catskill-hatchery">DEC Catskill Hatchery</L></strong> sits between the Beaverkill and the Willowemoc and is free to visit, with viewing areas and self-guided grounds.</p>
      <p>If it's Sunday, the <strong><L to="livingston-manor-farmers-market">Livingston Manor Farmers Market</L></strong> sets up on the front lawn in the heart of the hamlet, May through October.</p>
      <h2 className="trail-h2">Late morning — a brewery on a mountain</h2>
      <p>Livingston Manor has two of the best breweries in the Catskills. <strong><L to="upward-brewing-company">Upward Brewing</L></strong> sits on a 120-acre nature preserve called Beer Mountain, with hiking trails, mountain views, a pondside fire, and beer made from the preserve's own spring water (its BaseCamp LagerBier took a World Beer Cup silver). In town, <strong><L to="catskill-brewery">Catskill Brewery</L></strong> is a LEED-Gold microbrewery named Best Craft Brewery in the Hudson Valley at the 2025 Tap NY competition, with a taproom and beer garden. Either makes a great mid-morning stretch.</p>
      <h2 className="trail-h2">Midday — Roscoe, "Trout Town USA"</h2>
      <p>A short drive brings you to Roscoe, where the Beaverkill and Willowemoc meet at the famous Junction Pool. Lunch at <strong><L to="roscoe-beer-company">Roscoe Beer Company</L></strong>, home of the Trout Town line in a converted firehouse with a seasonal beer garden and live music. Right downtown, <strong><L to="prohibition-distillery">Prohibition Distillery</L></strong> occupies a 1929 firehouse and VFW hall, making the award-winning Bootlegger 21 vodka, gin, and bourbon, with tastings daily.</p>
      <h2 className="trail-h2">Afternoon — Callicoon on the Delaware</h2>
      <p>Head west to Callicoon, a handsome hamlet right on the Delaware River. The showpiece here is <strong><L to="seminary-hill-orchard-cidery">Seminary Hill Orchard &amp; Cidery</L></strong> — the world's first Passive House-certified cidery, clad in larch reclaimed from the old Tappan Zee Bridge, with a cathedral-ceilinged tasting room, an orchard-to-table restaurant, and a wraparound patio looking over the orchard and the Delaware Valley. It's worth the trip on its own. In the village, <strong><L to="callicoon-brewing-company">Callicoon Brewing</L></strong> pours ten taps in the 1880s Olympia Hotel overlooking the river, and <strong><L to="catskill-provisions-distillery">Catskill Provisions</L></strong> makes its well-known honey whiskey in another former firehouse.</p>
      <p>For provisions, Callicoon is farm-rich: <strong><L to="diehl-homestead-farm">Diehl Homestead Farm</L></strong> is a fourth-generation market open daily (maple, honey, dairy, eggs, meat, garlic), and <strong><L to="tonjes-farm-dairy">Tonjes Farm Dairy</L></strong> is an eighth-generation raw-milk creamery making farmstead Gouda, yogurt, kefir, and fresh mozzarella.</p>
      <h2 className="trail-h2">If you've got more time</h2>
      <ul className="trail-list">
        <li><strong>The Bethel arm — Woodstock history.</strong> <strong><L to="catskill-distilling-company">Catskill Distilling Company</L></strong> in Bethel makes Peace Vodka directly across the road from the original 1969 Woodstock site — now the Bethel Woods Center for the Arts, with its excellent museum and summer concerts. The tasting room has an original art deco bar from the 1939 World's Fair.</li>
        <li><strong>The Delaware River.</strong> <strong><L to="lander-s-river-trips">Lander's River Trips</L></strong> has outfitted rafting, kayaking, and tubing on the <strong><L to="upper-delaware-scenic-and-recreational-river">Upper Delaware Scenic &amp; Recreational River</L></strong> since 1955 — calm flatwater and a little whitewater at Skinner's Falls, with bald eagles overhead.</li>
        <li><strong>Narrowsburg.</strong> One of the most creative small towns in the Catskills, with a <strong><L to="narrowsburg-farmers-market">Saturday market</L></strong> above the Delaware and the <strong><L to="catskills-curated">Catskills Curated</L></strong> maker collective for Catskills-made goods.</li>
        <li><strong>Birding and a glass of wine.</strong> The <strong><L to="bashakill-wildlife-management-area">Bashakill Wildlife Management Area</L></strong> near Wurtsboro is the largest freshwater wetland south of the Adirondacks, with flat towpath trails; nearby <strong><L to="bashakill-vineyards-winery">Bashakill Vineyards</L></strong> pours organic wines. (Note: <strong><L to="aaron-burr-cider">Aaron Burr Cider</L></strong>, one of the most influential wild-apple cideries in America, is based nearby but has no public tasting room — worth knowing, not a drop-in.)</li>
        <li><strong>Fiber farms.</strong> <strong><L to="rosehaven-alpacas-fiber-mill">Rosehaven Alpacas &amp; Fiber Mill</L></strong> and <strong><L to="tonjes-farm-sheep-fiber">Tonjes Farm Sheep &amp; Fiber</L></strong>, both near Callicoon, sell yarn from their own animals.</li>
      </ul>
      <h2 className="trail-h2">A few practical notes</h2>
      <p>The producer-only Sunday markets in Callicoon and Livingston Manor are highlights if your timing lines up — both are seasonal. Seminary Hill's restaurant and Upward's kitchen are destinations in themselves, so consider reserving on busy weekends. The fly-fishing museum is open Friday through Monday, April through December. As always with the breweries and distilleries clustered here, bring a designated driver. And cell service gets thin out along the Delaware, so download your route first.</p>
      <p className="trail-crosslinks">The full Sullivan Catskills lineup is on the Almanac: <strong><Link to="/county/sullivan/craftbeverages">Sullivan County craft beverages</Link></strong> and <strong><Link to="/county/sullivan/markets">markets</Link></strong>.</p>
      <p className="trail-close">Trout streams, a river, the best cidery view in the Catskills — one very good Saturday.</p>
    </>
  ),
  "a-saturday-in-the-warwick-valley": () => (
    <>
      <p className="trail-lede">Tucked into the southwest corner of Orange County, the Warwick Valley is apple country in the grand sense — generations-old orchards rolling up to the Appalachian Trail, a historic downtown, working artisan studios, and one of the strangest and most fertile landscapes in the Northeast: the Black Dirt Region, a vast plain of jet-black muck soil that grows half the onions in New York State. It's farm-dense, beverage-rich, and less than ninety minutes from the city, so it gets busy on weekends. Here's a full day, anchored on Warwick with the Black Dirt and Sugar Loaf as arms.</p>
      <h2 className="trail-h2">Morning — downtown Warwick</h2>
      <p>Start in the village. On Sundays, the <strong><L to="warwick-valley-farmers-market">Warwick Valley Farmers' Market</L></strong> — Orange County's oldest, going since 1994 — fills the South Street lot with 30-plus regional farms, pastured meats, local wines, and chef demos. Any day, the <strong><L to="pennings-farm-market-orchard">Pennings Farm Market &amp; Orchard</L></strong> is a cornerstone destination: a year-round indoor market, garden center, farm-to-table grill, and beer garden on 100 acres. Wander the downtown either way — <strong><L to="bertoni-gallery">Bertoni Gallery</L></strong> has handcrafted jewelry made on-site since 1982.</p>
      <h2 className="trail-h2">Late morning — pick your own</h2>
      <p>This is what Warwick does best. <strong><L to="masker-orchards">Masker Orchards</L></strong> has been doing drive-right-to-the-tree apple picking on 200 rolling acres since 1913, no admission fee, with spectacular valley views. <strong><L to="ochs-orchard">Ochs Orchard</L></strong> is a four-generation farm with U-pick fruit nearly year-round and a market full of cider donuts, pies, and fresh-pressed cider. Pick a basket of something and keep the day moving.</p>
      <h2 className="trail-h2">Midday — cider and lunch at the pioneers</h2>
      <p>For lunch with a pour, you're spoiled. <strong><L to="warwick-valley-winery-distillery">Warwick Valley Winery &amp; Distillery</L></strong> is the elder statesman — home to Doc's Draft Hard Cider, one of New York's oldest, and in 2001 the first fruit microdistillery to open in the state since Prohibition. Its post-and-beam tasting room has a farm-to-table café, live music every weekend, and a 65-variety pick-your-own orchard. Or head to <strong><L to="pennings-farm-cidery">Pennings Farm Cidery</L></strong>, in an Amish-built barn with twelve taps, brick-oven Neapolitan pizza, and panoramic valley views from the Adirondack chairs.</p>
      <h2 className="trail-h2">Afternoon — into the Black Dirt</h2>
      <p>Drive west into the Black Dirt Region and the land goes flat and jet-black — drained swampland turned to some of the richest farm soil in America. This is onion country: <strong><L to="minkus-family-farms">Minkus Family Farms</L></strong> alone grows about half the onions in New York State, and <strong><L to="a-gurda-produce">A. Gurda Produce</L></strong> in Pine Island is a fifth-generation Black Dirt farm (both are largely wholesale operations, so for retail browsing aim for the Pine Island <strong><L to="warwick-indoor-farm-market">Warwick Indoor Farm Market</L></strong>, open Sundays year-round).</p>
      <p>The region's most distinctive drinks come straight out of this soil. <strong><L to="orange-county-distillery">Orange County Distillery</L></strong> at Brown Barn Farms in New Hampton grows its own grain on Black Dirt land — even distilling vodka from sugar beets — and shares the rustic post-and-beam barn with <strong><L to="orange-county-brewing-company">Orange County Brewing</L></strong>. Back toward Warwick, <strong><L to="drowned-lands-brewery">Drowned Lands Brewery</L></strong> takes its name from the region's pre-drainage swamp era, with a creek-side setting, fire pits, and a brick-oven pizza kitchen.</p>
      <h2 className="trail-h2">Late afternoon — makers and the best ice cream around</h2>
      <p>Swing through Sugar Loaf, where the <strong><L to="sugar-loaf-arts-craft-village">Sugar Loaf Arts &amp; Craft Village</L></strong> is a living hamlet of 50-plus working studios — potters, painters, glassmakers, woodworkers — in barns dating to the 1700s, where you can watch the artisans at work. <strong><L to="tin-barn-brewing">Tin Barn Brewing</L></strong> is right there if you want one more pint.</p>
      <p>Then end the day the right way: <strong><L to="bellvale-farms-creamery">Bellvale Farms Creamery</L></strong>, a seven-generation dairy atop Mount Peter making 50-plus flavors of small-batch ice cream from its own herd, with breathtaking Catskill and Warwick Valley views. It's ranked among the very best ice cream parlors in the country, it's a beloved stop for Appalachian Trail hikers, and it's open April through October. A cone here at golden hour is the perfect closer.</p>
      <h2 className="trail-h2">If you've got more time</h2>
      <ul className="trail-list">
        <li><strong>More breweries.</strong> <strong><L to="long-lot-farm-brewery">Long Lot Farm Brewery</L></strong> and <strong><L to="rushing-duck-brewing">Rushing Duck</L></strong> in Chester, <strong><L to="glenmere-brewing-company">Glenmere Brewing</L></strong> in Florida (gold-medal Farmhouse Ale), and <strong><L to="fence-road-farm-brewery">Fence Road Farm Brewery</L></strong> in Warwick, which also has an 18-hole disc golf course.</li>
        <li><strong>Apple Dave's &amp; Applewood.</strong> <strong><L to="apple-daves-distillery">Apple Dave's Distillery</L></strong> makes 1840s-style freeze-distilled Apple Jack on a 130-acre orchard, sharing a campus with <strong><L to="applewood-winery">Applewood Winery</L></strong> and <strong><L to="naked-flock-hard-cider-mead">Naked Flock</L></strong> cider and mead.</li>
        <li><strong>Orchard Hill Cider Mill</strong> in New Hampton — <strong><L to="orchard-hill-cider-mill">estate cider, pommeau, and apple brandy</L></strong> at Soons Orchards, with a farm-to-table taproom the *Times* has praised.</li>
        <li><strong>For makers.</strong> <strong><L to="5-spoke-creamery">5 Spoke Creamery</L></strong> in Goshen makes raw-milk farmstead cheese, and <strong><L to="catskill-merino-sheep-farm">Catskill Merino Sheep Farm</L></strong> in Warwick hand-dyes its own yarn.</li>
        <li><strong>City Winery Hudson Valley</strong> in Montgomery — <strong><L to="city-winery-hudson-valley">a 130-year-old mill turned winery and concert venue</L></strong> if you want live music with dinner.</li>
      </ul>
      <h2 className="trail-h2">A few practical notes</h2>
      <p>The Warwick market is Sunday; Pennings and the orchard markets are open daily in season; pick-your-own apples run Labor Day into November. The big Black Dirt onion farms are wholesale operations — call ahead or shop the Pine Island indoor market instead. Bellvale is seasonal (April–October), so save it for a warm day. With this many cideries and distilleries clustered together, bring a designated driver. And being a quick hop from the city, Warwick fills up on fall weekends — go early.</p>
      <p className="trail-crosslinks">The full lineup is on the Almanac: <strong><Link to="/county/orange/craftbeverages">Orange County craft beverages</Link></strong> and <strong><Link to="/county/orange/food">farms &amp; food</Link></strong>.</p>
      <p className="trail-close">Black soil, old orchards, the best cone in the valley — one very good Saturday.</p>
    </>
  ),
  "a-saturday-in-the-western-catskills": () => (
    <>
      <p className="trail-lede">West of the high peaks, the Catskills soften into a quieter country — round-barn markets, book-village Main Streets, a heritage railroad, and some of the most farm-dense towns in the region. Delaware County doesn't get the weekend crush that the eastern mountaintop does, and that's exactly its appeal. Here's a Saturday built around the Route 28 and Route 30 corridor near Arkville and Margaretville, with everything close enough to do at an unhurried pace.</p>
      <p>Most of the farm markets here are Saturday-morning affairs that close by early afternoon, so start with one and let the rest of the day unspool from there.</p>
      <h2 className="trail-h2">Morning — the Round Barn</h2>
      <p>There's no better place to begin than the <strong><L to="pakatakan-farmers-market">Pakatakan Farmers Market</L></strong> at the historic Round Barn in Halcottsville, a few miles up Route 30 from Margaretville. Running since 1991 and now past its 33rd year, it's one of the most beloved markets in the Catskills — vegetables, pasture-raised meats, trout, artisan cheeses, breads, maple, and crafts, with breakfast and brunch vendors and picnic tables that make it as much a gathering as a grocery run. Saturdays, roughly 9 to 1, mid-May into November. Fuel up here and stock the cooler.</p>
      <h2 className="trail-h2">Late morning — ride the rails</h2>
      <p>A few minutes south at Arkville, the <strong><L to="delaware-ulster-railroad">Delaware &amp; Ulster Railroad</L></strong> runs heritage excursions along the East Branch of the Delaware, tracing a line first laid in 1866 — and back in service since 2025 after years dark. The short run is about 75 minutes round-trip to Halcottsville, with beaver, deer, and bald eagles along the river. If you'd rather move under your own power, the <strong><L to="catskill-scenic-trail">Catskill Scenic Trail</L></strong> runs 26 mostly-flat miles on an old railbed through Bloomville and Roxbury — walk or bike as much or as little as you like.</p>
      <h2 className="trail-h2">Midday — lunch and Main Street in Andes</h2>
      <p>Head east on Route 28 to Andes, one of Delaware County's most charming hamlets and a genuine foodie pocket. <strong><L to="wayside-cider">Wayside Cider</L></strong> pours small-batch cider made from wild and abandoned homestead apple trees in a beautifully restored barn on Main Street, with a full bar of other local drinks, a rotating menu of small bites, and a fire pit out on the patio (well-behaved dogs welcome in the courtyard). It's the easy lunch anchor. While you're in town, the <strong><L to="andes-farmers-market">Andes Farmers Market</L></strong> runs Saturdays 10 to 2 in front of the Tin Horn if you didn't get your fill at Pakatakan.</p>
      <h2 className="trail-h2">Afternoon — makers and a tasting</h2>
      <p>Andes and its neighbors are quietly full of makers. <strong><L to="catskills-indigo">Catskills Indigo</L></strong> is an indigo-dyeing studio in an 18th-century barn where the artists grow their own dye plants and run weekend workshops in natural dyeing and cyanotype. Over in Bloomville, <strong><L to="turquoise-barn">Turquoise Barn</L></strong> builds furniture and lamps from reclaimed and found wood alongside natural-form sculpture.</p>
      <p>When you're ready for a tasting, swing back to Arkville, where <strong><L to="union-grove-distillery">Union Grove Distillery</L></strong> makes its award-winning Vly Creek Vodka from New York apples and wheat, plus a maple spirit made from local Tree Juice syrup, a rye, and a gin — with <strong><L to="calico-outlaw-brewing">Calico Outlaw Brewing</L></strong> sharing the same building, so it's a two-for-one stop.</p>
      <h2 className="trail-h2">Dinner, if you're making a night of it</h2>
      <p>Two of the area's best meals need a plan ahead. <strong><L to="bovina-farm-fermentory">Bovina Farm &amp; Fermentory</L></strong> in Bovina Center is a 20-acre farmstead brewery, restaurant, and inn where guests share candlelit communal tables for prix-fixe farm dinners — booked by email — and can stay over in one of four farmstead units. <strong><L to="greenane-farms">Greenane Farms</L></strong> in Meridale runs a farm-to-table restaurant serving wood-fired meats and authentic Mexican cuisine, Thursday through Saturday, seasonally. Either turns a day trip into a weekend.</p>
      <h2 className="trail-h2">If you've got more time</h2>
      <ul className="trail-list">
        <li><strong><L to="plattekill-mountain">Plattekill Mountain</L> — Roxbury.</strong> A family-owned mountain *Powder Magazine* once called "the Alta of the Catskills." Skiing and snowtubing in winter; lift-served mountain biking, scenic chairlift rides, and free outdoor concerts in summer.</li>
        <li><strong>Hobart, the book village.</strong> The hamlet has reinvented itself around antiquarian bookstores, with the <strong><L to="hobart-farmers-market">Hobart Farmers Market</L></strong> Friday evenings June through September. Bookworm heaven.</li>
        <li><strong>Delhi.</strong> Catch the <strong><L to="strickland-hollow-farm-distillery">Strickland Hollow</L></strong> tasting room on Main Street (Calvados-style apple brandy) and stock up at the <strong><L to="lucky-dog-organic-farm">Lucky Dog Organic Farm</L></strong> store in nearby Hamden.</li>
      </ul>
      <h2 className="trail-h2">A few practical notes</h2>
      <p>The markets set the clock: Pakatakan runs Saturday mornings, the Bovina market is Friday 4–7, and Andes is Saturday 10–2 — plan around whichever you want most. The standout dinners (Bovina, Greenane) need reservations and run seasonally, so book before you drive. Check the railroad's schedule before counting on a ride. And out here, cell coverage gets thin between towns — download your directions before you lose signal.</p>
      <p className="trail-crosslinks">The full Western Catskills lineup is on the Almanac: <strong><Link to="/county/delaware/markets">Delaware County markets</Link></strong> and <strong><Link to="/county/delaware/craftbeverages">craft beverages</Link></strong>.</p>
      <p className="trail-close">Quieter mountains, slower roads, one very good Saturday.</p>
    </>
  ),
  "a-saturday-in-troy-and-rensselaer-county": () => (
    <>
      <p className="trail-lede">Troy is one of the Hudson Valley's great comeback stories — a Gilded Age river city of cast-iron storefronts and brownstones that's become a magnet for makers, brewers, and one of the best farmers markets in the Northeast. Ring the city with multi-generation farms, a plateau of hill-country homesteads, and a fertile valley running east to Vermont, and Rensselaer County makes a satisfying day that balances a walkable downtown with real farm country. Here's a loop built around Troy.</p>
      <h2 className="trail-h2">Morning — the Troy Waterfront</h2>
      <p>Start downtown at the <strong><L to="troy-waterfront-farmers-market">Troy Waterfront Farmers Market</L></strong>, the Capital Region's premier market — 80-plus producers and makers every Saturday, year-round, outdoors around Monument Square from May through October and indoors at the Uncle Sam Atrium the rest of the year. It's producer-only and genuinely excellent, with grass-fed meat, raw cheese, mushrooms, bread, and prepared food. Give yourself time to wander Troy's restored streets while you're at it.</p>
      <p>The city is thick with makers, too. <strong><L to="prism-glassworks">Prism Glassworks</L></strong> has been hand-blowing glass art since 2001 (with lessons and bench rentals), and <strong><L to="the-broken-mold-studio-2">The Broken Mold Studio</L></strong> is a pottery shop and community studio. For later, <strong><L to="browns-brewing-troy">Brown's Brewing</L></strong> — brewing on the Troy riverfront since 1993, one of the oldest craft breweries in the state — has a waterfront taproom with live music.</p>
      <h2 className="trail-h2">Late morning — heritage breeds</h2>
      <p>Just southeast of the city in West Sand Lake, <strong><L to="june-farms">June Farms</L></strong> is a 120-acre heritage-breed sanctuary — Scottish Highland cows, giant Shire horses, Gloucestershire Old Spot and Tamworth pigs, Nigerian dwarf goats — dedicated to preserving breeds that predate factory farming, and open for farm visits. It's a joyful, only-here kind of stop, especially with kids.</p>
      <h2 className="trail-h2">Midday — pick-your-own and a farm lunch</h2>
      <p>The river towns south of Troy are farm-rich. <strong><L to="kristy-s-barn">Kristy's Barn</L></strong> in Schodack is a century farm (since 1910) with U-pick strawberries, apples, and pumpkins, a farm store famous for its apple cider donuts and housemade pies, plus weekend hayrides and a petting paddock — a great midday anchor. Nearby, <strong><L to="best-berry-farm">Best Berry Farm</L></strong> in East Greenbush has been a U-pick tradition since 1979, and <strong><L to="engelke-farm">Engelke Farm</L></strong> near Troy runs a greenhouse, U-pick, and a full fall pumpkin-patch experience minutes from downtown. Gardeners should detour to <strong><L to="becker-s-farm">Becker's Farm</L></strong> in East Greenbush, a garden center in continuous operation since 1870.</p>
      <h2 className="trail-h2">Afternoon — a farm brewery to finish</h2>
      <p>Head south to Nassau and <strong><L to="ss-farm-brewery">S&amp;S Farm Brewery</L></strong>, a New York Farm Brewery on a sixth-generation family farm that milked Holsteins into the late 1990s — the original brewhouse was built right in the old milk house. They grow their own crops, pour beers like the pre-Prohibition-style Old 82 golden ale, and host food trucks, live music, and a playground for families. Open Friday evenings with extended summer hours, it's a fitting farm-country close to the day.</p>
      <h2 className="trail-h2">If you've got more time</h2>
      <ul className="trail-list">
        <li><strong>The Hoosick Valley (east toward Vermont).</strong> <strong><L to="berle-farm">Berle Farm</L></strong> in Hoosick Falls is a certified-organic 15-cow dairy making artisanal cheese, yogurt, and raw milk alongside beef and apples, with a farm store April through December — this is also Grandma Moses and Bennington Battlefield country.</li>
        <li><strong>Schaghticoke's farm belt.</strong> <strong><L to="denison-farm">Denison Farm</L></strong> is a certified-organic farm on Battenkill bottomland continuing the legacy of New York's oldest CSA, and the <strong><L to="schaghticoke-fair">Schaghticoke Fair</L></strong> over Labor Day is the third-oldest fair in the state.</li>
        <li><strong>The Rensselaer Plateau.</strong> The hill towns east of Troy — Averill Park, Grafton, Poestenkill, Berlin — have a string of small markets (the <strong><L to="poestenkill-farmers-market">Poestenkill</L></strong> Saturday market is a gem) and the <strong><L to="rensselaer-plateau-farm-school">Rensselaer Plateau Farm School</L></strong> in Grafton, which teaches cheesemaking, butchery, and fermentation. Grafton Lakes State Park is right up there for a swim or a hike.</li>
        <li><strong>For cheese lovers.</strong> <strong><L to="four-fat-fowl">Four Fat Fowl</L></strong> makes the cult-favorite St. Stephen triple-cream, and the <strong><L to="hudson-mohawk-weavers-guild">Hudson-Mohawk Weavers' Guild</L></strong> holds a much-loved Show &amp; Sale each November.</li>
      </ul>
      <h2 className="trail-h2">A few practical notes</h2>
      <p>The Troy market is the rare year-round, every-Saturday anchor — reliable in any season, which makes Troy the easiest place to base the day. Most of the farms (Kristy's Barn, Best Berry, Engelke) run seasonally, roughly May through Thanksgiving, with U-pick peaking in summer and fall. S&amp;S is Friday-evening-and-weekend, so plan the farm-brewery finish accordingly, and bring a designated driver if you're adding Brown's. The plateau and Hoosick corners are genuinely rural, so service thins out east of the city.</p>
      <p className="trail-crosslinks">The full Rensselaer lineup is on the Almanac: <strong><Link to="/county/rensselaer/food">farms &amp; food</Link></strong> and <strong><Link to="/county/rensselaer/markets">markets</Link></strong>.</p>
      <p className="trail-close">A river city reborn, century farms all around it — one very good Saturday.</p>
    </>
  ),
  "a-saturday-on-the-helderberg-back-roads": () => (
    <>
      <p className="trail-lede">West of the Helderberg escarpment, the land climbs into a quiet upland of hilltowns — Berne, Knox, Westerlo, Rensselaerville — that feel a world away from Albany twenty miles east. This is high, remote, beautiful country: rare-breed sheep and alpacas, sugarhouses on hillside woodlots, grass-fed farms down dirt roads, a 4,500-acre wilderness, and a storybook hamlet with a waterfall at its edge. It's back-roads farming at its most authentic — small honor stands and by-appointment fiber farms where the discovery is half the point. (It's the southwestern companion to the Almanac's other Helderberg guide, which stays up on the Thacher escarpment.) Here's a Saturday circuit through the hilltowns.</p>
      <h2 className="trail-h2">Morning — Berne &amp; East Berne</h2>
      <p>Start in the hilltown heart around Berne, which has become a small capital of fiber farming. <strong><L to="helder-herdwyck-farm">Helder~Herdwyck Farm</L></strong> in East Berne raises rare Herdwick sheep — the second flock in the United States and the first east of the Rockies, the very breed Beatrix Potter championed — selling Herdwick wool, roving, and yarn alongside pastured meats and eggs from a farm store. Down the road, <strong><L to="helderberg-alpacas">Helderberg Alpacas</L></strong> keeps a herd of Huacaya alpacas bred for fiber, with yarn and farm visits by appointment, and <strong><L to="roots-n-boots">Roots N Boots</L></strong> is a homesteader-minded nursery tucked into the escarpment.</p>
      <p>For provisions, <strong><L to="frantzen-s-scenic-acres-farm">Frantzen's Scenic Acres Farm</L></strong> sells pasture-raised chicken, heritage turkeys, and brown eggs, and <strong><L to="partridge-run-farm-and-apiary">Partridge Run Farm and Apiary</L></strong> is open daily for raw wildflower honey and handmade soap. Then stretch your legs at <strong><L to="partridge-run-wildlife-management-area">Partridge Run Wildlife Management Area</L></strong> — 4,500 acres on West Mountain, among the highest ground in Albany County, with 40-plus miles of old fire roads and single-track, ponds, and waterfalls in the southern section. It's remote and largely unmarked, which is exactly its charm.</p>
      <h2 className="trail-h2">Midday — Knox &amp; Westerlo</h2>
      <p>Loop west to Knox and <strong><L to="longfield-farm">Longfield Farm</L></strong>, a one-stop farm store with grass-fed and pasture-raised meats, vegetables and flowers, stone-hearth artisan bread, and local wool — a great spot to gather lunch. Nearby, <strong><L to="helderberg-1839-maple-vine">Helderberg 1839 Maple &amp; Vine</L></strong> is a boutique maple farm that makes not just syrup, sugar, and confections but a maple wine fermented entirely from its own syrup. Drop south to Westerlo for <strong><L to="eight-mile-creek-farm">Eight Mile Creek Farm</L></strong>, a certified-organic family farm with a CSA, vegetables, grass-fed beef, and a homesteader-oriented nursery.</p>
      <h2 className="trail-h2">Afternoon — Rensselaerville &amp; the falls</h2>
      <p>The day's gem is Rensselaerville, a beautifully preserved historic hamlet of white clapboard and stone that feels frozen a century back. At its edge, the Huyck Preserve protects thousands of acres around Lake Myosotis and Rensselaerville Falls, with quiet trails to the cascade — one of the loveliest short walks in the region. <strong><L to="kuhar-family-farm">Kuhar Family Farm</L></strong>, right by the preserve, grows produce, eggs, and mushrooms and runs a small farm-to-table kitchen serving weekend brunch. Just outside the village, <strong><L to="a-promise-to-gaia">A Promise to Gaia</L></strong> is a 106-acre land-stewardship project with a nine-acre lake, native-plant sales, and a contemplative retreat.</p>
      <h2 className="trail-h2">Late afternoon — Preston Hollow</h2>
      <p>Drift south toward the Greene County line and <strong><L to="heather-ridge-farm-bees-knees-cafe">Heather Ridge Farm &amp; Bees Knees Café</L></strong> in Preston Hollow — a diversified grass-fed farm with a store full of its own beef, lamb, goat, and chicken plus woolen goods, and a café serving a farm lunch on Saturdays. It's the natural place to end, and it sits right at the doorstep of the Almanac's Oak Hill guide if you want to roll on into the Durham Valley farms.</p>
      <h2 className="trail-h2">If you've got more time</h2>
      <ul className="trail-list">
        <li><strong>More maple.</strong> <strong><L to="bittersweet-maple-farm">Bittersweet Maple Farm</L></strong> and <strong><L to="mountain-winds-farm">Mountain Winds Farm</L></strong>, both in Berne, make hillside syrup and join NYS Maple Weekend with wagon rides and pancake breakfasts each spring.</li>
        <li><strong>More small farms.</strong> <strong><L to="howard-and-kristine-zimmer">Howard and Kristine Zimmer</L></strong> in East Berne sell pasture-raised meat direct (call ahead), and <strong><L to="good-day-honey">Good Day Honey</L></strong> in Coeymans Hollow keeps a sustainable apiary.</li>
      </ul>
      <h2 className="trail-h2">A few practical notes</h2>
      <p>This is genuinely remote back-roads country, so plan ahead: many of these farms are honor stands or by-appointment (Helderberg Alpacas, the Zimmers), maple shines in spring during Maple Weekend, and the Bees Knees Café keeps a narrow Saturday lunch window — worth routing your day around if you want to eat there. Partridge Run is large, wild, and largely unmarked, so bring GPS and good shoes. Cell service is spotty up in the hilltowns; download your directions before you climb. And this loop hands off neatly to the Oak Hill guide at the Greene County line if you're making a bigger day of it.</p>
      <p className="trail-crosslinks">The full Albany County lineup is on the Almanac: <strong><Link to="/county/albany/food">farms &amp; food</Link></strong> and <strong><Link to="/county/albany/maple">maple</Link></strong>.</p>
      <p className="trail-close">Rare sheep on a hillside, a waterfall behind a white-steepled village, syrup boiled from the trees out back — one very good Saturday.</p>
    </>
  ),
  "a-saturday-on-the-mountaintop": () => (
    <>
      <p className="trail-lede">Up here, the Catskills rearrange themselves around two roads. Route 23 runs the ridge through Windham; Route 23A drops down through Hunter and Tannersville toward the escarpment. Between them sits a string of mountain villages where the farm stands, sugar houses, breweries, and Main Street makers are close enough together that you can fill a whole Saturday without ever leaving the high country.</p>
      <p>Here's a loop that does it: a morning in Windham, a swing west through Prattsville to Gilboa, and an afternoon working back east through Hunter and Tannersville. Pace it loosely, bring someone to drive the back half, and remember you're at elevation — mountain weather and seasonal hours both have opinions, so a call ahead never hurts.</p>
      <h2 className="trail-h2">Morning — Windham</h2>
      <p>Start on Main Street with coffee and something warm. <strong><L to="babblers-bakery">Babblers Bakery</L></strong> and <strong><L to="la-patisserie-normande">La Patisserie Normande</L></strong> both turn out croissants and pastries fresh — the Normande side leans properly French if you're in a cheesecake mood.</p>
      <p>If it's a Saturday in season, the <strong><L to="windham-farmers-market">Windham Farmers' Market</L></strong> is the social heart of the mountain on Saturday mornings, mid-May through late October — local produce, meats, cheeses, maple, honey, soaps, and live music, all in one stop.</p>
      <p>Then point the car west on Route 23 and pull in at the <strong><L to="catskill-mountain-country-store">Catskill Mountain Country Store</L></strong>, a Windham institution since 1994. Homemade jams, maple syrup, honey, fudge, and award-winning baked goods up front; the Happy Sappy Maple Museum, farm animals, and a playground out back. A TasteNY stop and an easy place to stock the cooler before the drive.</p>
      <h2 className="trail-h2">Midday — west to Prattsville and Gilboa</h2>
      <p>Keep heading west into farm-stand country.</p>
      <p>In <strong>Prattsville</strong>, <strong><L to="rsk-farm">RSK Farm</L></strong> on Route 23A is Robert and Sandra Kiley growing vegetables right in the fields behind the stand — sweet corn, heirloom potatoes, tomatoes, the works, plus local honey and maple (open mid-July through November). A short way on, <strong><L to="mossy-stone-farms">Mossy Stone Farms</L></strong> is a certified-organic market garden on Route 10, a clean source for mountain-grown vegetables.</p>
      <p>Then make the run down to Gilboa, where the Schoharie Creek opens up. <strong><L to="sunken-city-cider">Sunken City Cider</L></strong> is your midday anchor, and the name carries real local history — it honors the Village of Old Gilboa, drowned under the Schoharie Reservoir in 1926. Partner-owner Elisabeth was born and raised right there on Stryker Road. The cidery sits on a 70-acre former dairy farm, pours 100% New York hard cider (naturally sugar-free and gluten-free) under an open pavilion with mountain views off the creek, and runs food trucks most weekends. A scenic, story-rich place to land for a while.</p>
      <h2 className="trail-h2">Afternoon — back east through Hunter and Tannersville</h2>
      <p>Work your way back east and stretch your legs at the <strong><L to="mountain-top-arboretum">Mountain Top Arboretum</L></strong> in Tannersville — 200 acres at 2,400 feet, with boardwalks through meadows and wetlands and a calendar of foraging, herbalism, and botany workshops. Members free; $5 suggested for everyone else.</p>
      <p>Tannersville's Main Street — the painted village — is worth a slow walk. <strong><L to="fromer-market-gardens">Fromer Market Gardens</L></strong> runs a year-round organic farm stand right on Main, one of the only year-round local food sources on the mountain. <strong><L to="bones-and-stones">Bones &amp; Stones</L></strong> handcrafts one-of-a-kind knives and antler work. <strong><L to="catskills-candle-studio">Catskills Candle Studio</L></strong> hand-pours candles in scents that smell like the woods outside. And <strong><L to="last-chance-antiques-cheese-cafe">Last Chance Antiques &amp; Cheese Café</L></strong> has been pairing specialty cheese with antiques for as long as anyone can remember.</p>
      <p>Finish with a beer. <strong><L to="hunter-mountain-brewery">Hunter Mountain Brewery</L></strong> pours 15-plus of its own on tap with pub food (including vegan and gluten-free) just below the highest peak in the Northern Catskills, and it's a stop on the Catskills Beverage Trail. If you'd rather end back in Windham, <strong><L to="vineyard-at-windham">The Vineyard at Windham</L></strong> pours flights with charcuterie at the base of Windham Mountain, and <strong><L to="mountain-king-brewing">Mountain King Brewing</L></strong> has a taproom right on Main.</p>
      <h2 className="trail-h2">If you've got more daylight</h2>
      <p>The mountaintop has more than one Saturday in it. Save these:</p>
      <ul className="trail-list">
        <li><strong><L to="north-south-lake-campground-beach">North–South Lake</L> — Haines Falls.</strong> The most popular spot in the Catskill Park: two lakes at 2,200 feet beside the old Catskill Mountain House site, with the escarpment trail running out to Kaaterskill Falls and Artist Rock and panoramic Hudson Valley views. Open May through Columbus Day.</li>
        <li><strong>The maple trail.</strong> <strong><L to="partridge-sugar-house">Partridge Sugar House</L></strong> in Ashland has made Catskill maple since 1898 — five generations, wood-fired, no additives. <strong><L to="mountaintop-maple">Mountaintop Maple</L></strong> works a 110-acre Jewett farmstead, and <strong><L to="burt-s-mountain-honey">Burt's Mountain Honey</L></strong> brings in raw honey off the hives around Windham and Ashland Pinnacle.</li>
        <li><strong><L to="newton-farm-collective">Newton Farm Collective</L> — West Kill.</strong> Biodynamic vegetables on an 1807 homestead, a farm stand, foraging and fermentation workshops, and a record shop in the farmhouse.</li>
      </ul>
      <h2 className="trail-h2">A few practical notes</h2>
      <p>Saturday markets close early — Windham's runs roughly 9 to 1 — so do the market first. Several farm stands are seasonal (RSK opens mid-July), so call ahead in spring and late fall. Bring a designated driver for the cidery and breweries. And dress for the mountain: it's cooler and changeable up at 2,000-plus feet, even when the valley's warm.</p>
      <p className="trail-crosslinks">The full lineup of mountaintop makers — every maple producer, brewery, and farm in the directory — is on the Almanac: <strong><Link to="/county/greene/craftbeverages">Greene County craft beverages</Link></strong> and <strong><Link to="/county/greene/maple">Greene County maple &amp; honey</Link></strong>. (Sunken City sits just over the line in <strong><Link to="/county/schoharie/craftbeverages">Schoharie County</Link></strong>.)</p>
      <p className="trail-close">One ridge, two roads, one very good Saturday.</p>
    </>
  ),
  "hudson-valley-craft-beverage-trail": () => (
    <>
      <p className="trail-lede">Somewhere along the way, the Hudson Valley and the Catskills became one of the great craft-beverage landscapes in America — and it wasn't an accident. It grew out of orchards and grain fields and one quietly important law. Today the Almanac lists roughly 180 cideries, breweries, distilleries, and wineries across the region, more than any other single thing we track besides the farms themselves. This is the guide to the whole landscape: how it happened, what you'll find, where it clusters, and how to build a day around a glass.</p>

      <h2 className="trail-h2">How a region became a craft-beverage capital</h2>
      <p>The deep root goes back to 1839, when <strong><L to="brotherhood-winery">Brotherhood</L></strong> opened in Washingtonville — America's oldest continuously operating winery, with stone-walled underground cellars you can still tour. For a century and a half it was an outlier.</p>
      <p>The thing that turned a handful of wineries into a whole movement happened in Gardiner in 2003, when <strong><L to="tuthilltown-spirits-distillery">Tuthilltown Spirits</L></strong> became the first legal whiskey distillery to open in New York since Prohibition. Its founder's advocacy is the reason New York's Farm Distillery Act exists — the law that let small producers distill, ferment, and pour on their own farms using their own crops. Almost every farm cidery and distillery in this guide owes its existence to that fight. The boom that followed is what you're driving through now.</p>

      <h2 className="trail-h2">The four pours</h2>
      <p>Roughly, here's what's out there (some places make more than one, so the lines blur):</p>
      <p><strong>Breweries — about 88, the deepest bench.</strong> From city comeback stories to nano farm breweries growing the hops out back. <strong><L to="browns-brewing-troy">Brown's Brewing</L></strong> has brewed on the Troy riverfront since 1993; <strong><L to="mill-house-brewing-company">Mill House</L></strong> sits in a 19th-century mill in Poughkeepsie, <strong><L to="clemson-brothers-brewery">Clemson Brothers</L></strong> in an old Middletown hacksaw factory, and <strong><L to="frog-alley-brewing">Frog Alley</L></strong> anchors downtown Schenectady. The farm-brewery end is the soul of it: <strong><L to="plan-bee-farm-brewery">Plan Bee</L></strong> brews exclusively from its own land, <strong><L to="long-lot-farm-brewery">Long Lot</L></strong> grows the hops behind the brewhouse on a fifth-generation dairy farm, and <strong><L to="bovina-farm-fermentory">Bovina Farm &amp; Fermentory</L></strong> is a 20-acre farmstead brewery, restaurant, and inn deep in the Western Catskills.</p>
      <p><strong>Distilleries — about 49.</strong> Whiskey, bourbon, vodka, and gin, much of it field-to-glass. <strong><L to="hillrock-estate-distillery">Hillrock Estate</L></strong> in Ancram grows and floor-malts its own grain on a working farm; <strong><L to="coppersea-distilling">Coppersea</L></strong> in West Park revives heritage grain-to-glass methods; <strong><L to="1857-spirits-barbers-farm-distillery">1857 Spirits</L></strong> distills estate potato vodka from potatoes grown on the same Schoharie Valley farm. Sullivan County turned two old firehouses into distilleries — <strong><L to="prohibition-distillery">Prohibition Distillery</L></strong> in a 1929 firehouse in Roscoe and <strong><L to="catskill-provisions-distillery">Catskill Provisions</L></strong> in a former Callicoon one.</p>
      <p><strong>Cideries — about 31, the most "Hudson Valley" of all.</strong> Almost every one is rooted in an orchard. <strong><L to="slyboro-ciderhouse">Slyboro</L></strong> presses at Hicks Orchard, New York's oldest U-pick; <strong><L to="bad-seed-hard-cider">Bad Seed</L></strong> ferments at the sixth-generation Wilklow Orchards (1855); <strong><L to="rose-hill-ferments">Rose Hill Ferments</L></strong> works a Dutchess orchard founded in 1798; <strong><L to="sunken-city-cider">Sunken City</L></strong> pours over the Schoharie Creek; and <strong><L to="hardscrabble-cider">Hardscrabble</L></strong> at Harvest Moon Farm is Westchester's only cidery.</p>
      <p><strong>Wineries &amp; meaderies — about 15.</strong> Beyond Brotherhood, <strong><L to="clinton-vineyards">Clinton Vineyards</L></strong> has made its signature Seyval Blanc since 1977, <strong><L to="hudson-chatham-winery">Hudson-Chatham</L></strong> was Columbia County's first, and <strong><L to="warwick-valley-winery-distillery">Warwick Valley Winery &amp; Distillery</L></strong> has been a pioneering three-in-one farm operation since 1994.</p>

      <h2 className="trail-h2">Where it clusters</h2>
      <p>The whole region is rich, but the density is real in the southern Hudson Valley. By county, where the listings concentrate:</p>
      <ul className="trail-list">
        <li><strong><Link to="/county/ulster/craftbeverages">Ulster</Link> (25)</strong> — the birthplace, around New Paltz, Gardiner, and Kingston.</li>
        <li><strong><Link to="/county/orange/craftbeverages">Orange</Link> (23)</strong> — Warwick and the Black Dirt, plus the historic Brotherhood corner.</li>
        <li><strong><Link to="/county/dutchess/craftbeverages">Dutchess</Link> (19)</strong> — Beacon, Poughkeepsie, and the Red Hook orchards.</li>
        <li><strong><Link to="/county/westchester/craftbeverages">Westchester</Link> (14)</strong> and <strong><Link to="/county/sullivan/craftbeverages">Sullivan</Link> (13)</strong> — the river cities, and the Sullivan firehouse distilleries.</li>
        <li><strong><Link to="/county/greene/craftbeverages">Greene</Link> (12)</strong>, <strong><Link to="/county/columbia/craftbeverages">Columbia</Link> (12)</strong>, and <strong><Link to="/county/saratoga/craftbeverages">Saratoga</Link> (10)</strong> — the home-county Catskills, the field-to-glass belt, and the spa-town brewery bench.</li>
        <li><strong><Link to="/county/warren/craftbeverages">Warren</Link> (9)</strong> — a tight Lake George cluster of lakeside breweries and distilleries.</li>
      </ul>

      <h2 className="trail-h2">A few good beverage-trail days</h2>
      <p>Most of the Farm Trails guides already thread the tasting rooms through them. The ones that lean hardest into a glass:</p>
      <ul className="trail-list">
        <li><strong>Tuthilltown country.</strong> New Paltz, Gardiner, and the Rondout, built around the distillery that started it all. → <strong><Link to="/farm-trails/a-saturday-in-the-shawangunks">A Saturday in the Shawangunks</Link></strong></li>
        <li><strong>Orchards into cider.</strong> Warwick's apples become Pennings, Apple Dave's, Orchard Hill, and the Black Dirt distilleries. → <strong><Link to="/farm-trails/a-saturday-in-the-warwick-valley">A Saturday in the Warwick Valley</Link></strong></li>
        <li><strong>The firehouse distilleries.</strong> Roscoe and Callicoon, plus Bethel and the Delaware. → <strong><Link to="/farm-trails/a-saturday-in-the-sullivan-catskills">A Saturday in the Sullivan Catskills</Link></strong></li>
        <li><strong>A lakeside crawl.</strong> Adirondack Pub &amp; Brewery, Bolton Landing, and two distilleries with Lake George as the backdrop. → <strong><Link to="/farm-trails/a-saturday-in-lake-george">A Saturday in Lake George</Link></strong></li>
        <li><strong>Field to glass.</strong> Hillrock and Hudson-Chatham anchor a Columbia County day of estate distilleries and barrel-makers. → <strong><Link to="/farm-trails/a-saturday-in-columbia-county">A Saturday in Columbia County</Link></strong></li>
        <li><strong>The spa-town bench.</strong> Saratoga's brewpubs on foot, then Dancing Grain — the county's only farm brewery — looking out over its own grain fields. → <strong><Link to="/farm-trails/a-saturday-in-saratoga">A Saturday in Saratoga</Link></strong></li>
      </ul>

      <h2 className="trail-h2">A few practical notes</h2>
      <p>Tasting-room hours skew to the weekend — many farm cideries and distilleries run Thursday or Friday through Sunday, so weekend afternoons are the sweet spot; call ahead before a weekday drive. Because so many are licensed farm producers, they're often right on the orchard or grain field that supplies them, which makes them a natural pair with U-pick, a farm store, or a market in the same trip. And the one rule that matters most: with this many cideries, breweries, and distilleries clustered together, always bring a designated driver.</p>
      <p className="trail-crosslinks">The full list, county by county, lives on the Almanac — start with <strong><Link to="/county/ulster/craftbeverages">Ulster</Link></strong>, <strong><Link to="/county/orange/craftbeverages">Orange</Link></strong>, or <strong><Link to="/county/dutchess/craftbeverages">Dutchess</Link></strong>, or browse the <strong><Link to="/farm-trails">Farm Trails guides</Link></strong> for a route that's already mapped.</p>
      <p className="trail-close">A 19th-century cellar, a firehouse still, an orchard pressed into cider — one very good glass at a time.</p>
    </>
  ),
};
